-- One history entry per seeded drink, so trends start from the first known price.
select d.pub_id, d.id, d.name, d.category, d.measure, d.current_price, d.last_updated_at, d.source, d.source_url
from public.drinks d
where not exists (select 1 from public.price_reports r where r.drink_id = d.id);

