insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-blue-posts-berwick-street', 'The Blue Posts', '22 Berwick Street, Soho, London W1F 0QA', 'Soho', 51.51331, -0.13521, null, array['historic', 'food', 'live-music', 'comedy', 'sing-along']::text[], 'A traditional Soho corner pub by the Berwick Street market. One of several Blue Posts pubs in the area, supposedly named after the posts that marked the old royal hunting grounds.', 'https://www.theblueposts.net/', 'https://www.theblueposts.net/drinks', null, 'Unknown (check)', '{"0":[["11:30","22:30"]],"1":[["11:30","23:00"]],"2":[["11:30","23:00"]],"3":[["11:30","23:00"]],"4":[["11:30","23:00"]],"5":[["11:30","23:00"]],"6":[["11:30","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-blue-posts-berwick-street', 'no', 'Several London pubs are called The Blue Posts; theblueposts.net is the 22 Berwick Street one (general@theblueposts.net, 020 7437 5008). Hosts comedy (Mon/Wed) and music (Tue/Thu). Seed drinks and prices are guesses.') on conflict (pub_id) do nothing;
