insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-porterhouse', 'The Porterhouse', '21-22 Maiden Lane, Covent Garden, London WC2E 7NA', 'Covent Garden', 51.51077, -0.1231, 2000, array['craft-beer', 'irish-pub', 'live-music', 'sports-tv', 'food', 'beer-garden']::text[], 'A sprawling multi-level Irish brewpub full of brass and copper pipework, pouring Porterhouse''s own stouts and ales alongside a long bottle list.', 'https://porterhouse.london/', 'https://porterhouse.london/wp-content/uploads/2026/04/QR-Code-Drinks-Menu-Spring-2026-Version-2.pdf', 'https://porterhouse.london/wp-content/uploads/2026/09/Autumn-Food-Menu-2026.pdf', 'Porterhouse Brewing Co. (independent)', '{"0":[["12:00","22:00"]],"1":[["12:00","00:00"]],"2":[["12:00","00:00"]],"3":[["12:00","00:00"]],"4":[["12:00","00:00"]],"5":[["12:00","00:00"]],"6":[["12:00","00:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-porterhouse', 'yes', '[Sep 2026 research] Publishes PDF drinks menus WITH PRICES. Current menu: ''QR Code Drinks Menu Spring 2026 Version 2'' (https://porterhouse.london/wp-content/uploads/2026/04/QR-Code-Drinks-Menu-Spring-2026-Version-2.pdf), found by Archie; its prices still need entering. Older menus for comparison: Oct 2024 Temple Lager £6.60, Yippy IPA £6.80, Oyster Stout £6.80, Budvar £6.90 a pint; halves £3.10-£3.65. Our seed drinks (Plain Porter, Hop Head, Stonewell Cider) may not be on the current menu. Events page: https://porterhouse.london/events/ (live music Thu-Sat, Irish session Sun afternoons). 18 screens for sport, especially rugby; listed on Fanzo: https://www.fanzo.com/en/bar/248658/the-porterhouse. 30+ taps. Phone 020 7379 7917.') on conflict (pub_id) do nothing;
