insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-ship-tavern', 'The Ship Tavern', '12 Gate Street, Holborn, London WC2A 3HP', 'Holborn', 51.51712, -0.11846, 1549, array['historic', 'food', 'victorian-interior', 'live-music', 'sports-tv']::text[], 'A tavern said to date back to 1549, rebuilt in 1923. It''s known for its wood-panelled rooms and stories of secret Catholic masses held here in Tudor times.', 'https://theshiptavern.co.uk/', 'https://theshiptavern.co.uk/menus/drink-menu/', 'https://theshiptavern.co.uk/menus/', 'Independent (Ev Inns; Heineken UK freehold)', '{"0":[["11:00","23:00"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","00:00"]],"5":[["11:00","00:00"]],"6":[["11:00","00:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
