insert into public.pub_admin (pub_id, prices_online, notes) values ('the-alleyns-head', 'yes', '[26 Sep 2026] Added on request. Ember Inns pub with four regular cask ales (CAMRA), garden, car park, board games. Hours: Mon-Sat 11:30-23, Sun 11:30-22:30. Phone 020 8670 6540. Offers page: https://www.emberinns.co.uk/nationalsearch/london/the-alleyns-head-west-dulwich/news (cask ale ''from £3.50 a pint'', likely an Ember Rewards offer, not the normal price; 2 cocktails £13.50 from 5pm). Weekly quiz mentioned, but no day found: ask and add it as an event. DRINKS ARE GUESSES: check at the bar.') on conflict (pub_id) do nothing;
