insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-rosendale', 'The Rosendale', '65 Rosendale Road, West Dulwich, London SE21 8EZ', 'West Dulwich', 51.4368, -0.0946, null, array['historic', 'food', 'beer-garden', 'dog-friendly', 'quiz-night']::text[], 'A Grade II listed former Victorian coaching inn with a pillared portico and original Royal Doulton tiles. It has three gardens with a children''s play area, table tennis and boules, and a dining room serving seasonal food.', 'https://www.therosendale.co.uk/', 'https://www.therosendale.co.uk/assets/PAGE-1-SPRING-2026-1.pdf', 'https://www.therosendale.co.uk/menus/', 'Three Cheers Pub Co.', '{"0":[["11:00","22:30"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","01:00"]],"6":[["11:00","01:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-rosendale', 'yes', '[25 Sep 2026] Added on request, with the Spring 2026 drinks menu PDF (page 1, sent in by the user). 13 draught/cask prices entered as pints (the menu doesn''t say pint or half: check at the bar). Menu spells it ''Gypsy Hill Hepcat Session IPA''; the brewery is Gipsy Hill, so entered as ''Gipsy Hill Hepcat''. Lucky Saint is 0.5% alcohol-free. Also on the menu but not added (not beer): summer spritzers £10.50 (Aperol, Limoncello, Hugo, Campari), classic cocktails £11.50 (Sriracha Bloody Mary £10), ''Garden Greats'' cocktails £11.50, mocktails £6. Page 1 only: there may be more pages (bottles, wine). Pub: 65 Rosendale Road SE21 8EZ, 020 8761 9008, Instagram @therosendalepub. Grade II listed, mid-19th-century front, former Victorian coaching inn; opening year unknown. Three gardens (play area, table tennis, boules), two private rooms (East and West Rooms), dog friendly. Hours (listing): Mon-Thu 11-23, Fri-Sat 11-01, Sun 11-22:30. Events: Monday pub quiz (teams up to 6, £2.50 each per a 2023 listing: check it still runs and the start time); pilates and seasonal events mentioned. What''s on: https://www.therosendale.co.uk/whats-on/ . Menus: https://www.therosendale.co.uk/menus/ ; offers: https://www.therosendale.co.uk/offers/ ; CAMRA: https://camra.org.uk/pubs/rosendale-dulwich-158685 . CHECK MAP PIN: coordinates are the postcode centre, not the building.') on conflict (pub_id) do nothing;
