insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-crown-and-greyhound', 'The Crown & Greyhound', '73 Dulwich Village, London SE21 7BJ', 'Dulwich Village', 51.449367, -0.0848, 1900, array['historic', 'food', 'beer-garden', 'live-music']::text[], 'A big Grade II listed village pub built around 1900 to replace two rival pubs, The Crown and The Greyhound; locals call it "The Dog". It reopened in March 2026 after a refurbishment, with a garden, a dining room and rooms upstairs.', 'https://www.thecrownandgreyhound.co.uk/', 'https://www.thecrownandgreyhound.co.uk/menus/drink', 'https://www.thecrownandgreyhound.co.uk/menus/food', 'Mitchells & Butlers (Castle)', '{"0":[["11:00","22:30"]],"1":[["09:00","23:00"]],"2":[["09:00","23:00"]],"3":[["09:00","23:00"]],"4":[["09:00","23:00"]],"5":[["09:00","00:00"]],"6":[["09:00","00:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-crown-and-greyhound', 'yes', '[26 Sep 2026] Added on request. Grade II listed, built about 1900 to replace The Crown and The Greyhound (across the street from each other until the 1890s); locals call it ''The Dog''. Reopened 19 March 2026 after a refurbishment. 2-4 changing real ales (CAMRA); cocktails about £12-13; set menus 2 courses £25 / 3 courses £28; Sunday roast. Garden, 20 bedrooms. EVENTS: ''Jazz after Dark'' live jazz on various dates from Fri 4 Sep 2026; Thu 8 Oct 7pm seeded as a one-off. No quiz found. DRINKS ARE GUESSES: no prices found online; check the website''s menu pages and add real prices and menu links.') on conflict (pub_id) do nothing;
