insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-wood-house', 'The Wood House', '39 Sydenham Hill, London SE26 6RS', 'Dulwich Wood', 51.4327, -0.0728, null, array['food', 'beer-garden', 'quiz-night', 'live-music', 'sports-tv']::text[], 'A Young''s pub on Sydenham Hill by Dulwich Wood, built in the Victorian era to a design by Joseph Paxton of Crystal Palace fame. It has a big, partly covered and heated garden with an outside bar, a conservatory restaurant and a weekly quiz.', 'https://www.thewoodhousedulwich.co.uk/', 'https://www.thewoodhousedulwich.co.uk/food-drink', 'https://www.thewoodhousedulwich.co.uk/food-drink', 'Young''s', '{"0":[["09:00","23:00"]],"1":[["10:30","23:00"]],"2":[["10:30","23:00"]],"3":[["10:30","23:00"]],"4":[["10:30","23:00"]],"5":[["09:00","23:00"]],"6":[["09:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-wood-house', 'partial', '[26 Sep 2026] Added on request. Also called Dulwich Wood House; brands itself ''Dulwich'' but the address is Sydenham Hill SE26, so it''s in its own ''Dulwich Wood'' area. Designed by Joseph Paxton (Crystal Palace); refurbished and reopened May 2015 with a conservatory restaurant. Big half-covered, heated garden with an outside bar and a Burger Shack; DOUGHP pizza; Sunday roast. Shows big sport (World Cup 2026, Wimbledon). thewoodhouse@youngs.co.uk, 020 8693 5666. EVENTS: weekly quiz, one listing says Wednesday 8pm, another says a Thursday quiz hosted by Paul Partridge: check which. ''Music sessions'' also listed (day not found). What''s on: https://www.thewoodhousedulwich.co.uk/whats-on . DRINKS ARE GUESSES: Young''s pub, so check the real range and prices.') on conflict (pub_id) do nothing;
