insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-argyll-arms', 'The Argyll Arms', '18 Argyll Street, London W1F 7TP', 'Soho', 51.515096, -0.141281, 1868, array['historic', 'victorian-interior', 'food', 'outdoor-drinking']::text[], 'Built in 1868 and refitted around 1895, this Grade II* pub by the London Palladium has one of London''s best surviving late-Victorian interiors, with etched glass and mahogany screens dividing the front into small snugs under a Lincrusta ceiling. It''s a busy Nicholson''s house just off Oxford Circus serving cask ales, pies and pub classics.', 'https://www.nicholsonspubs.co.uk/restaurants/london/theargyllarmsoxfordcircuslondon', 'https://www.nicholsonspubs.co.uk/restaurants/london/theargyllarmsoxfordcircuslondon/drinks', 'https://www.nicholsonspubs.co.uk/restaurants/london/theargyllarmsoxfordcircuslondon/food', 'Nicholson''s (Mitchells & Butlers)', '{"0":[["11:00","22:30"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","00:00"]],"6":[["11:00","00:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-argyll-arms', 'yes', '[29 Sep 2026 research] New pub. Nicholson''s (Mitchells & Butlers). Built 1868, interior remodelled c.1895 (Robert Sawyer); Grade II* (Historic England 1066496); CAMRA National Inventory, three stars. Brands itself ''Oxford Circus''; CAMRA and Wikipedia place it in Soho. Prices from Nicholson''s own data (seen 28 Sep 2026): draught from the order-at-table menu, bottles/low-no from the same menu and the web drinks menu (identical). M&B IDs: brand 112, brand scalable 09b752ce-97c8-5b9b-ab92-6cb9b533561f, BunCode 176737, outlet scalable 7aa025e6-8437-55b1-a42b-6bfd5dad89b4, sales area f32ca83c-7c8f-57f4-bccd-401d4b8d00c6, TradingEntity 1000310 (method in the Dog and Duck notes). Web drinks API: api-production.mbplc.io/webappbff/api/v1/menus/dynamic?id=1000310&idType=TradingEntity&tradingEntityId=1000310&websitePageUrlPath=drinks-menu1&salesChannel=DynamicWebMenus (salesChannel is required, otherwise 400). Research check: a first order-at-table pull got Clachan data by mistake (shared scratch files); re-pulled with bunCode 176737 verified, and the prices match the public web drinks menu. CASK CONFLICT: CAMRA (5 Jul 2026) lists London Pride, Nicholson''s Pale Ale, Doom Bar + 5 rotating guests; the order-at-table menu has only Nicholson''s Pale Ale (2 pumps), Landlord and Haze Machine. London Pride and Doom Bar added unpriced: check the pumps in person. Haze Machine is on both the cask and draught menus (probably keg). Hours: pub site, M&B API and CAMRA agree; 24 Dec 2026 11:00-22:00, 25 Dec 11:00-19:00. Food 12:00-21:00 daily (CAMRA; the M&B API food times say ''Closed'', looks unpopulated). Wine 175ml £7.85-£10.15; Prosecco 125ml £7.95; cocktails £10.95-£13.50 (Aperol Spritz £12.95); 0% cocktails £7.50; spirits 25ml from £4.50. TAGS: sports-tv not added (CAMRA lists sports TV, but the M&B API has sportsEnabled false and the only sport page is a past Six Nations page). outdoor-drinking = pavement seating with umbrellas (CAMRA), no real garden. real-ale-specialist not added. No events found (Six Nations page is retrospective; Christmas page has set menus only). Deal lead not entered: ''25% off when you sign up'' appears only as the offers page title, no terms: https://www.nicholsonspubs.co.uk/restaurants/london/theargyllarmsoxfordcircuslondon/offers . Upstairs restaurant/function rooms; family-friendly until 20:30 (CAMRA).
