insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-clachan', 'The Clachan', '34 Kingly Street, London W1B 5QH', 'Soho', 51.513497, -0.140265, 1898, array['historic', 'victorian-interior', 'food', 'sports-tv']::text[], 'A French Renaissance-style corner pub of 1898 just off Carnaby Street, once owned by the Liberty department store. Inside is a large mahogany island bar with etched glass, Lincrusta ceilings and a raised snug at the back. It''s a busy Nicholson''s pub serving cask ale and pies.', 'https://www.nicholsonspubs.co.uk/restaurants/london/theclachankinglystreetlondon', 'https://www.nicholsonspubs.co.uk/restaurants/london/theclachankinglystreetlondon/drinks', 'https://www.nicholsonspubs.co.uk/restaurants/london/theclachankinglystreetlondon/food', 'Nicholson''s (Mitchells & Butlers)', '{"0":[["12:00","22:00"]],"1":[["11:30","23:00"]],"2":[["11:30","23:00"]],"3":[["11:30","23:30"]],"4":[["11:30","23:30"]],"5":[["11:30","00:00"]],"6":[["11:30","00:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-clachan', 'yes', '[29 Sep 2026 research] New pub. Nicholson''s (Mitchells & Butlers, freehold per CAMRA). Built 1898; Grade II (list no. 1061360, 2002); CAMRA Real Heritage Pub (one star). Once owned by Liberty, sold 1993. Wikipedia says 33 Kingly Street; the pub site says 34 (used). Prices from the order-at-table menu (seen 28 Sep 2026); bottle prices match the web drinks menu. M&B IDs: brand 112, brand scalable 09b752ce-97c8-5b9b-ab92-6cb9b533561f, BunCode 177466, outlet scalable d7970bfe-8083-5677-80c4-3c2e783fd8f4, sales area 8e25e9d1-ada6-5c4c-a1e1-337a2e740af0, TradingEntity 1000350. Web drinks API needs salesChannel=DynamicWebMenus. HOURS CONFLICT: pub site and M&B API open 11:30 Mon-Tue (used); CAMRA (5 Jul 2026) says 12:00. 24 Dec 2026 11:30-21:00; 25 Dec closed. Food from noon (CAMRA; the M&B API food times say ''Closed'', looks like a placeholder). CASK: order-at-table has Nicholson''s Pale Ale (2 lines), Landlord and Haze Machine; CAMRA lists London Pride and Doom Bar as regulars (added unpriced) plus recent sightings of Timothy Taylor Boltmaker 4%, Golden Best 3.4% and Blonde. Cask rotates: check in person. DEALS NOT ENTERED: Evening Deal (main + Nicholson''s Pale Ale, Amstel, Carling, Mortimer''s Orchard cider, 175ml house wine or draught soft drink; +£1 for premium lager or 250ml wine) shows no bundle price, days or times: https://www.nicholsonspubs.co.uk/restaurants/london/theclachankinglystreetlondon/evening-deal (ask the pub). Peroni bucket (6 x 330ml) £33.10 on the order-at-table menu: not entered as it is above the £30 price limit. Sport: ''Watch live sport'' page and Six Nations shown (CAMRA), no fixture list, so no event entered. Outdoor: CAMRA says ''Garden - until 5pm with tables & chairs'', probably pavement tables on Kingly Street; not tagged, confirm. Wine 175ml £7.85-£10.15; Prosecco 125ml £7.95; cocktails £10.95-£13.50; 0% cocktails £7.50; spirits 25ml from £4.40. Liberty Room upstairs for hire (40 seated / 60 standing, own bar). Cask Marque; family-friendly until 21:00 (CAMRA). History: local for firemen of Station No.12 and Special Constable Reserve officers (pub site).
