insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-old-coffee-house', 'The Old Coffee House', '49 Beak Street, Soho, London W1F 9SF', 'Soho', 51.51255, -0.13736, 1894, array['historic', 'food', 'sports-tv', 'dog-friendly', 'outdoor-drinking']::text[], 'First licensed in 1772 as the Silver Street Coffee House and rebuilt in 1894, this granite-fronted backstreet pub near Carnaby Street has been run by the Brodie family since the 1970s. Inside it''s dark panelling, a long wooden bar, old brewery mirrors and bric-a-brac, with a cosier back room by the fire and Brodie''s ales on cask.', null, null, null, 'Independent', '{"0":[["12:00","22:30"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","23:00"]],"6":[["11:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-old-coffee-house', 'no', '[29 Sep 2026 research] New pub. Independent: run by the Brodie family since the 1970s on a lease from Heineken UK (freeholder) (CAMRA, updated 30 Jul 2026). First licensed 1772 as the Silver Street Coffee House; current building 1894 (year entered). NO WEBSITE: Instagram https://instagram.com/theoldcoffeehouse ; Facebook https://www.facebook.com/p/The-Old-Coffee-House-Soho-100041091859705/ . NO PRICES ONLINE: no menu, nothing on pint-prices.com or pintprice.com; Facebook groups and Tripadvisor unreadable. Only hint: an Untappd user (27 Sep 2026) said cask Bethnal Green Bitter was ''knocking £7'' (not entered). Check prices in person or via Instagram. Brodie''s closed its Leyton brewery in 2018, but Brodie''s cask and keg beers are still poured here (CAMRA, Untappd Sep 2026); where they are brewed now is unconfirmed. Not entered: Otter Bitter (typical guest per CAMRA, popular on Untappd, not confirmed on now); Fosters, Amstel, Heineken, John Smith''s (Londonist 2018, out of date). POSTCODE CONFLICT: CAMRA and others W1F 9SF (used); OSM W1F 9HB; beerintheevening W1F 9SB. Hours from CAMRA only (match Londonist 2018). Food Mon-Fri 12:00-15:00, Sat-Sun 12:00-17:00 (CAMRA). Sky football on TV with the volume low (CAMRA), no schedule, so no event entered; live music ''occasionally''. Pavement seating, dog friendly, real fire, upstairs function room for hire. Step at the entrance; no ground-floor toilets.
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('nell-gwynne-tavern', 'Nell Gwynne Tavern', '1-2 Bull Inn Court, London WC2R 0NP', 'Covent Garden', 51.51024, -0.12284, null, array['historic', 'food', 'sports-tv']::text[], 'A tiny, dimly lit Young''s pub hidden down a tiled alleyway off the Strand, named after Nell Gwynne, the actress and mistress of Charles II. The Grade II-listed building is an early-19th-century rebuild of an older house. It''s cosy and often packed, with a free jukebox, Young''s cask ales and simple bar snacks.', 'https://www.thenellgwynne.com/', 'https://www.thenellgwynne.com/wp-content/uploads/sites/149/2025/11/Nell.pdf', 'https://www.thenellgwynne.com/food-and-drink', 'Young''s', '{"0":[["12:00","22:00"]],"1":[["12:00","22:00"]],"2":[["12:00","23:00"]],"3":[["12:00","23:00"]],"4":[["12:00","23:00"]],"5":[["12:00","23:00"]],"6":[["12:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('nell-gwynne-tavern', 'yes', '[29 Sep 2026 research] New pub. Young''s (Young & Co.''s Brewery; pub site footer and JSON-LD, CAMRA). Website brand ''The Nell Gwynne''; ''Nell Gwynne Tavern'' on the menu PDF, CAMRA, OSM and Wikipedia. PRICES: from the pub''s own ''Sample Drinks Menu'' PDF (made in Canva 2025-03-25, uploaded 2025-11-12, still linked from /food-and-drink on 28 Sep 2026), so Date seen = 2025-11-12. Sample menu from 2025, prices may have risen (Young''s usually raise prices yearly). Low/no prices also in the live page data (menu modified 2025-11-06) and match. Sitemap lists /menus/drinks-menu (lastmod 2026-02-05) and /menus/spritz-menu (2026-03-30), both 404 publicly: re-check later for newer prices. Bloody Nell: the PDF shows ''10'' then ''9.50'' underneath; unclear which applies on Sundays, confirm. Rekorderlig bottles listed as 330ml at £7.05 (usually 500ml; possible menu typo). Aperol Spritz £11; Pimm''s & Lemonade £5.20; wine 175ml from £7, bottles £27.50-£43; Beefeater 25ml £5.40; Jägermeister/Sambuca £4.95. OPENED left blank: ''Est. 1667'' is marketing; Historic England: early-19th-century refront/rebuild of a 17th/18th-century house; CAMRA: rebuilt late 1890s with Art Nouveau tiles. Grade II since 15 Jan 1973 (1066336). CAMRA: Young''s Original and Special regular plus up to 3 guests. Real cider lead: Sandford Orchards Devon Mist (CAMRA, Aug 2025, no price, may not be current; not entered). Old London Pub Explorer prices (e.g. Adnams £3.90) are from before Young''s; ignore. When Young''s took over is undocumented. No events: no What''s On page; free jukebox; CAMRA says sports TV for selected events such as the Six Nations (basis for sports-tv tag). Instagram https://www.instagram.com/nell_gwynne_tavern/ and Facebook not checked (blocked). Email info@thenellgwynne.com. Check in person: tap list and prices, guest casks, dog policy, sports TV. Wheelchair access limited (OSM). FHRS 414398.
