insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-sherlock-holmes', 'The Sherlock Holmes', '10-11 Northumberland Street, London WC2N 5DB', 'Westminster', 51.507294, -0.125245, 1957, array['historic', 'food', 'dog-friendly', 'outdoor-drinking']::text[], 'London''s original Sherlock Holmes theme pub, created in 1957 in the former Northumberland Arms using the collection from the 1951 Festival of Britain Holmes exhibition, with a recreation of Holmes''s 221b Baker Street sitting room upstairs. It''s a busy Greene King pub near Trafalgar Square with cask ales, food and a small roof terrace.', 'https://www.greeneking.co.uk/pubs/greater-london/sherlock-holmes', 'https://www.greeneking.co.uk/pubs/greater-london/sherlock-holmes/menu', 'https://www.greeneking.co.uk/pubs/greater-london/sherlock-holmes/menu', 'Greene King', '{"0":[["11:00","22:30"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","23:00"]],"6":[["11:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-sherlock-holmes', 'partial', '[29 Sep 2026 research] New pub. Greene King (Local Pubs - Heritage; venue 7967; 7967@greeneking.co.uk). Created by Whitbread in Dec 1957 from the Northumberland Arms (earlier the Northumberland Hotel) using the 1951 Festival of Britain Holmes exhibition; 221b sitting-room recreation upstairs. GK ''Premium Heritage'' refurb, reopened April 2025. NO OFFICIAL BEER PRICES: GK menu API (greeneking.co.uk/api/menus/getmenus/7967) has wine and cocktails only; order-and-pay is app-only. Cocktails £12.50, spritzes £13, 0% cocktails £11, Prosecco for one £7.75, wine 175ml £7.50-£14.40. Six pint prices from pint-prices.com (undated; Guinness £6.55 and Amstel £6.45 look low, maybe pre-refurb). CAMRA cask range: Morland Sherlock Holmes Pale Ale 4.0%, GK London Glory 4.0%, GK IPA 3.4%, Dr Watson''s Amber Ale 5.0% + 2 changing guests (added unpriced). ADDRESS: GK and CAMRA say 10 Northumberland Street, OSM 10-11 (used); beerintheevening postcode WC2N 5DA, but GK, CAMRA and OSM say WC2N 5DB (used). AREA: new area Westminster (GK calls it St James''s; OSM ''Westminster, Covent Garden''); Covent Garden is the nearest existing area. Hours: GK and CAMRA agree. Food Mon-Sat 11:00-22:00, Sun 11:00-21:00. Children until 21:00 (CAMRA). EVENTS: GK event feed empty on 28 Sep 2026; only generic GK seasonal promos (Halloween 31 Oct 2026, Christmas, St Patrick''s Day 2027), not entered. CAMRA member discount entered as a deal (''valid until 26 October'', year presumed 2026), unverified. GK app ''Spin to Win'' new-user reward (chance of a free pint) not entered. TAGS not added (optional): real-ale-specialist (Cask Marque, 4 regular casks + 2 guests) and sports-tv (CAMRA only). Roof terrace plus pavement tables. Rooms for hire: The Parlour, Sir Arthur Conan Doyle room (press also names The Library). Food hygiene 5 (2025-01-08). Awards: Cask Marque, Best Bar None. Wikipedia''s ''Noble Bachelor'' hotel reference is worth double-checking (trivia only).
