insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-red-lion-westminster', 'The Red Lion', '48 Parliament Street, London SW1A 2NH', 'Westminster', 51.502078, -0.12568, 1899, array['historic', 'victorian-interior', 'food', 'sports-tv', 'cellar-bar', 'outdoor-drinking']::text[], 'A tavern has stood on this Parliament Street site since at least 1434; the present narrow Flemish-style corner pub was rebuilt in the 1890s and keeps its carved mahogany bar-back, decorated ceiling and etched glass. Between Downing Street and Parliament, it is the traditional local of MPs and political journalists, with a division bell and prime ministers'' portraits in the bar. Today it''s a busy Fuller''s ale-and-pie house with cask ales, a cellar bar and an upstairs dining room.', 'https://www.redlionwestminster.co.uk/', 'https://www.redlionwestminster.co.uk/drink', 'https://www.redlionwestminster.co.uk/food/menus', 'Fuller''s', '{"0":[["11:00","22:30"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","23:00"]],"6":[["11:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-red-lion-westminster', 'no', '[29 Sep 2026 research] New pub. OPERATOR: Fuller''s (Fuller, Smith & Turner), part of the Fuller''s Ale & Pie chain, NOT Nicholson''s/M&B as first assumed (pub site title and footer, fullers.co.uk email, CAMRA freehold owner, Wikipedia; no Red Lion Westminster in the Nicholson''s sitemap). Sheet named ''The Red Lion''; Pub ID the-red-lion-westminster. NO DRINK PRICES ONLINE: the drink page is prose only; the Tenkites food menu (menuId redlionwestminster13) has no drinks; Tenkites IDs 1-25 probed, none with drinks; no order-and-pay link; not on pint-prices.com. pub-reviews.co.uk says pints ''about £6-£7'' (generic, undated, not used). Needs an in-person check. CAMRA: 3 handpumps on each part of the bar; 3 regular + 2 changing beers. No keg lagers, stouts or bottles named anywhere. HOURS: used the site''s Opening Times table (Mon-Sat 11-23, Sun 11-22:30). Homepage JSON-LD says Mon-Sat 11-22, Sun 11-21:30 (probably food hours). CAMRA (4 Jul 2026) says Sun 11-22. Cask Marque says 08-23 daily (page has placeholder text, unreliable). Food Mon-Sat 11-22, Sun 11-21:30 (pub site). Summer weekend breakfasts; no alcohol before 10:00 Sat or 12:00 Sun (CAMRA). OPENED: 1899 entered (CAMRA: rebuilt 1898-9; bar-back carved 1900); Historic England listing says c.1890. Tavern on the site by 1434. Grade II (1226437, 1983). CAMRA National Inventory rating conflicts: two stars on the CAMRA page, one star on London Pubs Group. Events: Fuller''s events feed empty (pubId 4F337462D14D4A26981DAA7FC311A367); Christmas page has menus only. Deal: CAMRA member 10% off real ales (unverified). No happy hour; ''friend of Fuller''s'' sign-up promises unspecified offers. Food: London Pride steak & ale pie £20.95; haddock £20.95; pie sharing board £39.95. Tags: sports-tv, cellar bar and narrow benches outside per CAMRA. Division bell; aircon; former licensee co-founded National Pubwatch. Dog policy not stated. Email redlionwestminster@fullers.co.uk. CAMRA WhatPub WLD/15971.
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-albert', 'The Albert', '52 Victoria Street, London SW1H 0NP', 'Westminster', 51.497667, -0.135515, 1862, array['historic', 'victorian-interior', 'food', 'sports-tv', 'dog-friendly']::text[], 'A Grade II-listed Victorian pub of the 1860s named after Prince Albert, and one of the few original buildings left on Victoria Street. It keeps ornate ceilings and etched glass, and a division bell for Parliament rings in the dining room. It''s a big, busy Greene King pub with cask ales, food, an upstairs restaurant and live football on TV.', 'https://www.greeneking.co.uk/pubs/greater-london/albert', 'https://www.greeneking.co.uk/pubs/greater-london/albert/menu', 'https://www.greeneking.co.uk/pubs/greater-london/albert/menu', 'Greene King', '{"0":[["08:00","23:30"]],"1":[["08:00","00:00"]],"2":[["08:00","00:00"]],"3":[["08:00","00:00"]],"4":[["08:00","00:00"]],"5":[["08:00","00:00"]],"6":[["08:00","00:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-albert', 'partial', '[29 Sep 2026 research] CLOSED FOR REFURBISHMENT UNTIL 24 OCT 2026: the Greene King page says ''temporarily closed for an exciting refurbishment... re-open on 24th October''; its hours API shows every day ''Closed - Investment''. Hours entered are CAMRA WhatPub''s pre-refurb hours (surveyed 14 May 2025, page updated 27 Sep 2026): recheck hours, range and prices after 24 Oct. New pub. OPERATOR: Greene King (venue 7161, 7161@greeneking.co.uk; WhatPub freehold owner), NOT Nicholson''s/M&B as first assumed (not in the Nicholson''s sitemap; formerly Taylor Walker branding). NO OFFICIAL BEER PRICES: GK menu API (greeneking.co.uk/api/menus/getmenus/7161) has wine and cocktails only; beer prices are app-only (order & pay). Cocktails £10.50, spritzes £11, 0% cocktails £9, Prosecco for one £7.75, wine 175ml £7.20-£14.25. Food e.g. fish & chips £19.95. Only community beer price: Estrella Galicia £7.60 from a London Pub Map Facebook post URL slug (undated, low confidence). Range from WhatPub regulars and Untappd check-ins (Sep 2026). GK''s generic ''Flint Eye'' and ''Prior Life'' text not confirmed for this pub (not entered). WhatPub licence: alcohol from 10:00 Mon-Sat and 12:00 Sun (08:00 opening is breakfast). Food 08:00-22:00 daily (WhatPub). OPENED: 1862 entered (GK, Wikipedia); WhatPub says 1864 rebuild; Historic England 1865-67. Replaced the Blue Coat Boy (recorded 1831). Grade II (1066148, 1973). Asset of Community Value (WhatPub). EVENTS: entered only the pub-specific dated events from the pub''s own GK event feed (geteventfeed/7161), all after reopening. Not entered: Bonfire Night Warm Up (5 Nov), Remembrance Sunday silence (8 Nov), ''open on Boxing Day'' (generic), and Premier League fixtures from the GK sport widget (Sky Sports and TNT Sports shown). GK description mentions live music but none is listed. Deals: CAMRA 25% off cask (one per transaction) until 26 Oct, but the pub is closed until 24 Oct, so only ~2-3 days. Not entered: GK app ''Spin to Win'' (chance of a free pint/main/pudding) and ''Accepts Matchday Discount'' (no terms). Awards: Cask Marque, TripAdvisor Travellers'' Choice 2024, Best Bar None. Food hygiene 5 (2025-01-10). Instagram @thealbertvictoria. Wikipedia''s taylor-walker.co.uk link is out of date.
insert into public.drinks (pub_id, name, category, measure, volume_ml, current_price, source, source_url, last_updated_at) values ('the-albert', 'Estrella Galicia', 'Lager', 'pint', null, 7.60, 'seed', null, now() - interval '23 days') on conflict (pub_id, name_normalized, measure) do nothing;
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('st-stephens-tavern', 'St Stephen''s Tavern', '10 Bridge Street, Westminster, London SW1A 2JR', 'Westminster', 51.50111, -0.12556, 1875, array['historic', 'victorian-interior', 'food', 'dog-friendly']::text[], 'A Grade II-listed 1875 tavern on Bridge Street directly opposite Big Ben, named after St Stephen''s Chapel, whose division bell still calls MPs back to vote. Restored and reopened by Hall & Woodhouse in 2003, it has ornate bars with carved woodwork, etched mirrors and tall windows onto Parliament Square. It serves Badger ales from Dorset and traditional pub food to office workers, politicians and tourists.', 'https://www.ststephenstavern.co.uk/', 'https://www.ststephenstavern.co.uk/our-drinks/', 'https://www.ststephenstavern.co.uk/our-food/', 'Hall & Woodhouse (Badger)', '{"0":[["09:30","22:00"]],"1":[["09:30","22:30"]],"2":[["09:30","22:30"]],"3":[["09:30","22:30"]],"4":[["09:30","22:30"]],"5":[["09:30","22:30"]],"6":[["09:30","22:30"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('st-stephens-tavern', 'no', '[29 Sep 2026 research] New pub. Hall & Woodhouse (Badger Brewery), managed pub. Current building 1875 (Grade II); closed in the 1980s, restored and reopened by Hall & Woodhouse in 2003 (pub ''Our Story'', Wikipedia). Pubs and Beer''s Swan Hotel 1750 / 1886 rebuild story is less reliable (not used). NO DRINK PRICES ONLINE: the drinks page just says ''Badger and Outland beers''; the Ten Kites wine list (viewthe.menu/xa27) has empty price fields; the Ten Kites food menu (viewthe.menu/xasy) is priced but has no drinks; no PDFs, no order-at-table. Only community prices, newest Jun 2024 (Fursty Ferret £6.20, entered). Not entered: Mortimer''s Orchard cider (only seen Feb 2023) and Badger Glorious Game (seasonal, 2016). Check in person: pint prices for Badger Best, Tanglefoot, the seasonal ale, lagers (brands unknown), cider; whether Outland craft beers are on keg. Pubs and Beer: 4 handpumps on each of 2 bars. COORDINATES: used Wikipedia (51.50111, -0.12556), which matches Pubs Galore; the pub site''s structured data (51.5011625, -0.1302123) is ~300 m west and looks wrong. Hours from the pub site; food 09:30-21:00 daily. WhatPub not checked (URL not found); pint-prices.com had no entry. No events (What''s On only points to Westminster Abbey and sightseeing; Christmas page for festive bookings). No deals: H&W lists ''Blue Light Card'' as a facility (discount not stated); ''Summer Sippers'' cocktails page (May 2025) has no prices. H&W lists ''Outdoor Space'', but a reviewer describes only a little standing room in the side alley, so outdoor-drinking not tagged. Upstairs dining room (2024 review). Email ststephenstavern.london@hall-woodhouse.co.uk. Instagram st_stephens_tavern; facebook.com/ststephenstavern. Site is Propeller headless WordPress/Next.js, readable with curl.
insert into public.drinks (pub_id, name, category, measure, volume_ml, current_price, source, source_url, last_updated_at) values ('st-stephens-tavern', 'Badger Fursty Ferret', 'Real Ale', 'pint', null, 6.20, 'seed', null, now() - interval '28 days') on conflict (pub_id, name_normalized, measure) do nothing;
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-museum-tavern', 'The Museum Tavern', '49 Great Russell Street, Bloomsbury, London WC1B 3BA', 'Bloomsbury', 51.51821, -0.126006, 1855, array['historic', 'victorian-interior', 'food', 'dog-friendly', 'beer-garden', 'outdoor-drinking']::text[], 'A Grade II-listed Victorian pub directly opposite the British Museum, tracing its history to the Dog and Duck of 1723 and renamed once the museum arrived. The 1850s building keeps its 1889 mahogany bar-back, mirrors and etched glass naming the old public, private and saloon bars, and Karl Marx is said to have drunk here. Today it''s a busy Greene King pub with cask ales and traditional pub food.', 'https://www.greeneking.co.uk/pubs/greater-london/museum-tavern', 'https://www.greeneking.co.uk/pubs/greater-london/museum-tavern/menu', 'https://www.greeneking.co.uk/pubs/greater-london/museum-tavern/menu', 'Greene King', '{"0":[["11:00","22:30"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","00:00"]],"6":[["11:00","00:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-museum-tavern', 'partial', '[29 Sep 2026 research] New pub. Greene King (Local Pubs - Heritage; venue 7222; 7222@greeneking.co.uk). NO OFFICIAL BEER PRICES: GK menu API (greeneking.co.uk/api/menus/getmenus/7222) has wine and cocktails only; beer prices are app-only (order & pay). Cocktails £10.50, spritzes £11, 0% cocktails £9, Prosecco for one £7.75, wine 175ml £7.20-£9.60 (cheaper than the Sherlock Holmes). Five pint prices from pint-prices.com (undated; Guinness £6.35 and Amstel £6.15 look low, same pattern as the Sherlock Holmes). Old PubsAndBeer prices (£4.90 cask, 2018) too old to use. CAMRA regular casks: Abbot, GK IPA, Tribute + 1 changing (typically Southwark Bermondsey Best). GK Our Beers page also lists Genevieve (GK x Thornbridge), possibly a GK-wide template (not entered). Theakston Old Peculier (Wikipedia) has not returned since the pandemic per CAMRA (not entered). OPENED: 1855 entered for the current building (c.1855-64, William Finch Hill and E. L. Paraire; interior refitted 1889); origins 1723 as the Dog and Duck, renamed mid-18th century (GK says 1759, CAMRA 1762). Grade II (NHLE 1330367); CAMRA Real Heritage Pub (regional). HOURS CONFLICT: Monday close 23:00 (GK, used) vs 22:30 (CAMRA). Food Mon-Sat 11-22, Sun 11-21 (CAMRA). AREA: new area Bloomsbury (Holborn is the nearest existing area). COORDINATES: GK structured data; Wikipedia''s are ~150 m west. Events: GK event feed empty (29 Sep 2026); only generic GK seasonal promos (Christmas, St Patrick''s Day 2027 etc.), not entered; ''Weekend Takeover'' ended. CAMRA member discount entered (25% off one cask beer per transaction, ''until 26 October'', year presumed 2026), unverified. GK app ''Spin to Win'' (chance of a free pint) not entered. Tags: GK says ''beer garden'', CAMRA lists Garden and pavement seating. real-ale-specialist not added (Cask Marque, 3 regulars + 1 guest; modest). Family friendly, WiFi.
