insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-lamb', 'The Lamb', '94 Lamb''s Conduit Street, Bloomsbury, London WC1N 3LZ', 'Bloomsbury', 51.52308, -0.11905, null, array['historic', 'victorian-interior', 'real-ale-specialist', 'food', 'beer-garden', 'outdoor-drinking', 'no-music-no-tv']::text[], 'One of London''s oldest pubs, dating from the 1720s, whose Grade II-listed Victorian interior keeps rare hinged ''snob screens'' at the bar, music-hall photographs and a working polyphon. Dickens, Ted Hughes and Sylvia Plath were among its drinkers. It''s a quiet Young''s house with no piped music, known for its real ale, with a small walled garden at the back.', 'https://www.thelamblondon.com', 'https://www.thelamblondon.com/food-drink', 'https://www.thelamblondon.com/food-drink', 'Young''s', '{"0":[["12:00","22:00"]],"1":[["12:00","23:00"]],"2":[["12:00","23:00"]],"3":[["12:00","23:00"]],"4":[["12:00","23:30"]],"5":[["12:00","23:30"]],"6":[["12:00","23:30"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-lamb', 'partial', '[29 Sep 2026 research] New pub. Young''s (Young & Co.''s Brewery). Refurbished May-June 2026 (CAMRA, updated 1 Sep 2026): ground floor kept, first floor expanded for dining, so older community prices may be stale. NO BEER OR CIDER PRICES ONLINE: the /food-drink page has wine, spritz, cocktails and alcohol-free only; none of the 7 PDFs (WP media API) has beer prices. Spritzes £10-£12.50; cocktails £12-£12.50; alcohol-free £4.55-£9.50; wine (Medium-G.pdf, 1 Apr 2026) 175ml from £7.35, e.g. Vialetto Pinot Grigio £7.35 / bottle £29.50. Only beer price: Estrella £6.65 (pint-prices, undated). DEALS NOT ENTERED (over the £30 limit / festive packages): Christmas bucket of 12 Peroni £70 and 12 Peroni 0.0% £61; festive wine pours £23 or £30 per person (glass of fizz + half bottle), all from the festive drinks PDF (created 15 May 2026): https://www.thelamblondon.com/wp-content/uploads/sites/197/2026/06/The-Lamb_1086_festive_drinks.pdf . Christmas party set menu via /christmas (not entered as an event). QUIZ: only CAMRA lists a Monday evening quiz; the pub''s What''s On is empty, so the event is entered unchecked and the quiz-night tag is not added until confirmed. CAMRA says changing guests typically from Five Points and Redemption. OPENED left blank: the pub says ''dating back to the 1720s'' (no exact year). CONFLICTS: pint-prices says ''live sports'' and postcode WC1N 1EA; CAMRA says quiet, no piped music, and the pub site gives WC1N 3LZ (used); sports-tv not tagged. AREA: Bloomsbury (OSM puts it in Holborn / Camden). Food Mon-Sat 12-21, Sun 12-20. Check in person: prices for Original, Special, Proper Job, Southwark LPA, the lager (Estrella?), Guinness (not confirmed) and Old Rosie. Access: 1-inch step, no accessible toilets. Upstairs function room 55 standing / 36 seated. Email lamb.bloomsbury@youngs.co.uk; instagram.com/lamb.bloomsbury; facebook.com/thelambbloomsbury.
insert into public.drinks (pub_id, name, category, measure, volume_ml, current_price, source, source_url, last_updated_at) values ('the-lamb', 'Estrella', 'Lager', 'pint', null, 6.65, 'seed', null, now() - interval '3 days') on conflict (pub_id, name_normalized, measure) do nothing;
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-fitzroy-tavern', 'The Fitzroy Tavern', '16 Charlotte Street, London W1T 2LY', 'Fitzrovia', 51.518549, -0.134708, 1897, array['historic', 'food', 'no-music-no-tv']::text[], 'The pub that gave Fitzrovia its name: from the 1920s it was the bohemian heart of the district, drawing Dylan Thomas, George Orwell, Augustus John and Nina Hamnett. Today it''s a quiet Sam Smith''s house with no music or TV, a restored Victorian-style interior of etched glass and mahogany booths, cask Old Brewery Bitter from oak casks and a full food menu.', 'https://fitzroytavern.co.uk/', 'https://fitzroytavern.co.uk/drinks/', 'https://fitzroytavern.co.uk/menus/', 'Samuel Smith''s', '{"0":[["12:00","22:30"]],"1":[["12:00","23:00"]],"2":[["12:00","23:00"]],"3":[["12:00","23:00"]],"4":[["12:00","23:00"]],"5":[["12:00","23:00"]],"6":[["11:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-fitzroy-tavern', 'no', '[29 Sep 2026 research] New pub. Samuel Smith Old Brewery (Tadcaster). Unusually for Sam Smith''s it has its own website (WordPress, dated 2026 food PDFs), but NO DRINK PRICES ONLINE: drinks page describes the range only; not in pint-prices.com''s dataset; CAMRA has no prices; TripAdvisor mentions are vague (''around EUR10'' Jul 2025; ''£25 for a double G&T and lager'' Oct 2024); Yelp ''£2 stout'' is stale. Context only, other Sam Smith''s pubs (not this one): Taddy Lager £6.40 at the Duke of Argyll and Glasshouse Stores (pint-prices, undated); Boak & Bailey Sep 2023 ~£7 Pure Brewed, ~£6 OBB. Check prices in person for OBB, Taddy, Pure Brewed, Wheat Beer, Extra Stout, Alpine Lager, Sovereign, Organic Cider (Taddy, Alpine, Sovereign and cider are the usual London range but not confirmed here; not entered). Nut Brown Ale (550ml bottle) in Untappd ''popular drinks'', undated, not entered. Drinks range confirmed by dated Sep 2026 Untappd check-ins. OPENED: 1897 entered = current building per the pub site''s rebuild date. CONFLICT: CAMRA says the building began as the Fitzroy Coffee House in 1883, became the ''Hundred Marks'' in 1887 and was renamed the Fitzroy Tavern in 1919. ADDRESS: 16 (pub site, used) vs 16A Charlotte Street (CAMRA). Hours: pub site and CAMRA agree. FOOD HOURS CONFLICT: pub site Mon-Fri 12-15 & 17-21, Sat 12-21, Sun 12-17; CAMRA Mon-Fri 12-15:30 & 16:30-21. Not entered as deals (not drink deals): Darts Package (darts, food, drinks, sharing boards) from £19.95 per person, pre-book (https://fitzroytavern.co.uk/darts-package/); small plates 3 for £24.95 / 5 for £39.50. No events: Sam Smith''s pubs have no music or TV; CAMRA ''Quiet''. TAGS: victorian-interior not added because the interior is a Sam Smith''s restoration (c.2016-17, CAMRA Pub Design Award 2017), not original; cellar-bar possible (downstairs seats 50) but unconfirmed. Whole upper floor is a function room with its own bar and handpumps (30 seated). History: Kleinfeld family from 1919 made it the bohemian hub; later Charrington''s, then Sam Smith''s. Email info@fitzroytavern.co.uk. Sam Smith''s chain-wide cash-only / no-phones rules reported by London x London, unverified here.
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-newman-arms', 'The Newman Arms', '23 Rathbone Street, Fitzrovia, London W1T 1NG', 'Fitzrovia', 51.51813, -0.13525, null, array['historic', 'food', 'cellar-bar']::text[], 'A narrow, low-ceilinged Fitzrovia pub in a 1720s building, licensed as a beer house from 1863 and a haunt of George Orwell, who is thought to have based the ''Proles'' Arms'' in 1984 on it. Today it''s a pies-and-pints pub with a busy ground-floor bar, a sofa-filled basement and a candlelit upstairs pie room.', 'https://www.thenewmanarms.co.uk', 'https://www.thenewmanarms.co.uk/_files/ugd/7d8c0e_179368d791ef4cfd8ae3efea3933484b.pdf', 'https://www.thenewmanarms.co.uk/_files/ugd/7d8c0e_179368d791ef4cfd8ae3efea3933484b.pdf', 'Aldrich Inns', '{"1":[["12:00","23:00"]],"2":[["12:00","23:00"]],"3":[["12:00","23:00"]],"4":[["12:00","23:00"]],"5":[["12:00","23:00"]],"6":[["12:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-newman-arms', 'yes', '[29 Sep 2026 research] New pub. Aldrich Inns (small independent London group: Bull & Egret, Goat in Boots, Jeremy Bentham, Lock & Lantern, White Bear; contact info@aldrichinns.com). Leasehold 202 Pub Co Ltd; freehold Cream Properties Ltd (CAMRA). Under new management since Feb 2025, which brought back the upstairs pie room. WEBSITE WARNING: newmanarms.co.uk (without ''the'') is an unrelated spam/lifestyle blog; the real site is https://www.thenewmanarms.co.uk (Wix). /menu is an empty Wix page; live menus are the two PDF links on the home page. PRICES: from the combined food and drinks PDF (Canva, dated 4 Apr 2026, still linked; pp.5-8 drinks, image-only, read visually and cross-checked with OCR). Cask ales not listed (''Ask about our cask ales''; CAMRA: 1 changing beer, Cask Marque) - check in person. Bottle sizes not stated. Other prices: spritzes £10; Passionfruit and Espresso Martini £12.50; Spicy Tommy''s Margarita £10.50; Barrel-Aged Old Fashioned £12; Black Velvet (Murphy''s & crémant) £12; house red/rosé 175ml £7, bottle £26. Not entered as deals: house double & mixer £10 (every day); hip-flask Negroni £13.50, refill £9. Pie & a Pint deal from the Pie & Pint PDF (26 May 2026): pie (chicken, ham hock & leek; shepherd''s pie; or wild mushroom pithivier) + pint of Murphy''s or Pillars Helles, £20, Mon-Fri 12-15. 12.5% discretionary service on restaurant bills. OPENED left blank: 1720s building; brands itself ''est. 1730''; first licensed as a beer house 1863 (CAMRA). Hours: Mon-Sat 12-23, SUNDAY CLOSED (pub site and CAMRA agree). Restaurant/pie room Mon-Sat 12-15 and 17-21:30. No events (Experiences page: ''not offering any experiences at the moment''); a Christmas 2026 page may appear later. Newman Passage beside it features in the film Peeping Tom. outdoor-drinking not tagged (informal pavement/archway standing only). Older CAMRA London Pubs Group page calls it Truman''s (out of date). Email info@thenewmanarms.co.uk; instagram.com/newmanarms; also on OpenTable.
