insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('ye-olde-cheshire-cheese', 'Ye Olde Cheshire Cheese', '145 Fleet Street, London EC4A 2BU', 'Fleet Street', 51.51434, -0.10718, 1667, array['historic', 'food', 'cellar-bar', 'dog-friendly', 'no-music-no-tv']::text[], 'A 17th-century chophouse rebuilt just after the Great Fire of 1666, reached down a narrow alley off Fleet Street, where Dickens, Dr Johnson, Mark Twain and Yeats all drank. Inside is a dark maze of panelled rooms over three levels, with sawdust on the floor, open fires and a vaulted cellar bar, serving only Samuel Smith''s beers alongside chophouse food.', 'https://ye-olde-cheshire-cheese.co.uk/', 'https://ye-olde-cheshire-cheese.co.uk/drinks/', 'https://ye-olde-cheshire-cheese.co.uk/menus/', 'Samuel Smith''s', '{"0":[["12:00","22:30"]],"1":[["12:00","23:00"]],"2":[["12:00","23:00"]],"3":[["12:00","23:00"]],"4":[["12:00","23:00"]],"5":[["12:00","23:00"]],"6":[["12:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('ye-olde-cheshire-cheese', 'no', '[29 Sep 2026 research] New pub. Samuel Smith Old Brewery (Tadcaster). Trading: Untappd draught check-ins on the evening of 28 Sep 2026. Has its own website with hours and priced food menus (Apr 2026 PDFs), but NO DRINK PRICES ONLINE and no dated 2025-26 per-drink price reports. Only hints: ''pints of ale around the £4-£5 mark'' (no beer named; pub-reviews.co.uk review dated 2/12/2025, ambiguous date); ''£2.90 a pint'' (pubsandbeer, Apr 2015, far too old). Not on pint-prices.com: the ''Cheshire Cheese'' there is the different pub on Crutched Friars (EC3N 2AP). Context only: Boak & Bailey paid £5.70 for OBB at an unnamed Sam Smith''s pub in 2023. Check in person: OBB, Taddy, Pure Brewed, Wheat Beer, India Ale, Extra Stout, any cider; and which bars are open (Front, Cheshire, Johnson and Cellar bars, Chop Room; not all open in daytime per an older report). Dark Mild listed in Untappd ''popular drinks'' but undated (not entered). PAYMENT (UNCONFIRMED): London x London (updated 12 Sep 2026) says Sam Smith''s pubs are cash-only, ban phones and laptops and forbid swearing; this is a chain-wide claim not verified for this pub - check before telling users ''cash only''. POSTCODE CONFLICT: EC4A 2BU (CAMRA and OSM, used) vs EC4A 2BP (pub website footer). Entrance down Wine Office Court. OPENED: 1667 = rebuilt after the Great Fire; a pub on the site since 1538 (Wikipedia, pub About page). Grade II since 1977. Hours: pub site and CAMRA agree. Food 12:00-14:30 and 18:00-21:00 (CAMRA); Cellar Bar menu all day. Food prices: fish & chips £21, steak & kidney pudding £19.95, rarebit £9.50. no-music-no-tv tag from Sam Smith''s house policy (London x London), not stated on the pub site. No events or deals (only Christmas menus and private hire of historic rooms). Accessibility: pub site says ''totally inaccessible for wheelchairs''. Mixed TripAdvisor reviews Jul-Aug 2025. Email info@yeoldecheshirecheese.com. CAMRA lists it as ''Olde Cheshire Cheese''.
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-black-friar', 'The Black Friar', '174 Queen Victoria Street, London EC4V 4EG', 'Blackfriars', 51.512102, -0.103716, 1875, array['historic', 'food', 'outdoor-drinking', 'dog-friendly']::text[], 'A wedge-shaped pub of about 1875 on the site of a medieval Dominican friary, remodelled around 1905 into London''s most extravagant Arts & Crafts interior, with marble, mosaics and copper reliefs of jolly friars. Saved from demolition in the 1960s by a campaign led by John Betjeman, it''s now a lively Nicholson''s pub opposite Blackfriars station, serving cask ale and pies.', 'https://www.nicholsonspubs.co.uk/restaurants/london/theblackfriarblackfriarslondon', 'https://www.nicholsonspubs.co.uk/restaurants/london/theblackfriarblackfriarslondon/drinks', 'https://www.nicholsonspubs.co.uk/restaurants/london/theblackfriarblackfriarslondon/foodmenu', 'Nicholson''s (Mitchells & Butlers)', '{"0":[["12:00","22:30"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:30"]],"4":[["11:00","23:30"]],"5":[["11:00","23:30"]],"6":[["11:00","23:30"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-black-friar', 'yes', '[29 Sep 2026 research] New pub. Nicholson''s (Mitchells & Butlers; freehold M&B per CAMRA). NAME: ''The Black Friar'' used (CAMRA, Historic England, Wikipedia and the fascia mosaic); Nicholson''s brands it ''The Blackfriar'' (website, outlet API). Prices from Nicholson''s own data (seen 28 Sep 2026): draught from the order-at-table menu, bottles/low-no from the same menu and the web drinks menu (overlapping prices identical; web menu lastModified 2026-09-28). M&B IDs: brand 112, brand scalable 09b752ce-97c8-5b9b-ab92-6cb9b533561f, BunCode 177032 (verified on every response), outlet scalable 1c6a1219-ebc0-5308-af57-0bda2ab6a84d, sales area 1dbbd17b-cb0a-57e1-beaa-faf53c6d1bd1, TradingEntity 1000329 (method in the Dog and Duck notes). Web drinks API: api-production.mbplc.io/webappbff/api/v1/menus/dynamic?id=1000329&idType=TradingEntity&websitePageUrlPath=drinks-menu1&salesChannel=12. Cask menu lists Nicholson''s Pale Ale and Tribute twice (same items); cask rotates. Guinness £8.10 is among the dearest Nicholson''s so far. Wine 175ml £7.85-£10.15; Prosecco £7.95 glass / £38 bottle; cocktails £10.95-£13.50; 0% cocktails £7.50; spirits from £4.65; Jäger Bomb £8; Pimm''s jug £30.50. OPENED: 1875 entered (Nicholson''s, CAMRA GBG, listing ''c1875''); CAMRA heritage text also says c.1873 and 1871-2. Remodelled c.1905 by H. Fuller-Clark with Henry Poole; rear ''Grotto'' 1917-21. Grade II* (NHLE 1285723, 1972); CAMRA National Inventory three stars; Asset of Community Value. HOURS CONFLICT: Saturday close 23:30 (Nicholson''s and M&B API, used) vs 23:00 (CAMRA). 24 Dec 2026 11:00-19:00; closed 25, 26 Dec and 1 Jan; 31 Dec 11:00-01:00. Food Mon-Sat 11:30-21:00, Sun 12:00-20:00 (CAMRA; the M&B API food times say ''Closed''). TAGS: victorian-interior NOT added (interior is Edwardian Arts & Crafts/Art Nouveau, 1905-21). dog-friendly and outdoor-drinking from CAMRA facilities (''Dog Friendly'', ''Garden'', ''Outside seating area''); no garden in heritage descriptions, probably pavement seating - check. real-ale-specialist not added (3 casks on the menu). no-music-no-tv unconfirmed. No events (/whats-on 404; offers page only generic brand news). Deal lead not entered: ''25% off when you sign up'' (offers page title only, no terms): https://www.nicholsonspubs.co.uk/restaurants/london/theblackfriarblackfriarslondon/offers . No CAMRA member discount listed. AREA: new area Blackfriars (City of London; ''City'' would also fit). Instagram @blackfriarpub (not checked).
