insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-old-bell-tavern', 'The Old Bell Tavern', '95 Fleet Street, London EC4Y 1DH', 'Fleet Street', 51.514059, -0.105191, null, array['historic', 'food', 'sports-tv']::text[], 'A small, snug Fleet Street pub said to have been built by Christopher Wren for the masons rebuilding St Bride''s Church after the Great Fire, on a site linked to Wynkyn de Worde''s early printing press. Inside are bare boards, half-panelling, a U-shaped bar, old press cuttings and a fine stained-glass window, with the back looking onto St Bride''s churchyard. It''s a Nicholson''s pub serving cask ale and pub food.', 'https://www.nicholsonspubs.co.uk/restaurants/london/theoldbelltavernfleetstreetlondon', 'https://www.nicholsonspubs.co.uk/restaurants/london/theoldbelltavernfleetstreetlondon/drinks', 'https://www.nicholsonspubs.co.uk/restaurants/london/theoldbelltavernfleetstreetlondon/foodmenu', 'Nicholson''s (Mitchells & Butlers)', '{"0":[["12:00","18:00"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","23:00"]],"6":[["11:00","21:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-old-bell-tavern', 'yes', '[29 Sep 2026 research] New pub (replaces the Knights Templar, which closed in 2023). Nicholson''s (Mitchells & Butlers; freehold M&B), open and trading. Prices from Nicholson''s own data (seen 28 Sep 2026): draught from the order-at-table menu (menus flagged canOrder 0 = browsable, not orderable, prices still listed), bottles/low-no also on the web drinks menu (identical). M&B IDs: brand 112, brand scalable 09b752ce-97c8-5b9b-ab92-6cb9b533561f, BunCode 180270 (verified on every response), outlet scalable c8b33988-4310-5d98-98cd-c2ca0a4a1f91, sales area 168e66bc-0fef-5639-a344-9f0121a106c3, TradingEntity 1000469. Web drinks API: api-production.mbplc.io/webappbff/api/v1/menus/dynamic?id=1000469&idType=TradingEntity&websitePageUrlPath=drinks-menu1&salesChannel=12. AMSTEL listed at £0.00 (all portions): left unpriced. CASK: order-at-table shows only Nicholson''s Pale Ale and Wainwright; CAMRA says 4 changing + 1 regular (Boltmaker spotted recently; typical guests London Pride, Landlord, Titanic Plum Porter) - check handpumps in person. The pub page blurb mentions Meantime London Lager and Pale Ale, but neither is on any menu (not entered). Wine 175ml £7.35-£9.25; Prosecco 125ml £7.20; cocktails £10.95-£12.95; 0% cocktails £6.95; spirits from £4.35; Pimm''s jug £29.50. HOURS: Nicholson''s and M&B API (early close Sat 21:00, Sun 18:00); CAMRA has later weekday openings (12:00 Mon-Wed and Sat, 11:30 Thu-Fri). 24 Dec 2026 11-18; closed 25, 26 Dec, 1 Jan; 31 Dec 11-01. Food Mon-Fri 12-20, Sat 12-18, Sun 12-16 (CAMRA). PHONE CONFLICT: 020 7583 0216 (Nicholson''s/M&B, used) vs 020 7583 0070 (CAMRA, probably old). OPENED left blank: listing says ''probably late C17, much altered''; tradition says Wren built it; a pub ''by 1678'' per an unverified Facebook post. Grade II (NHLE 1064658); CAMRA Local Inventory; Asset of Community Value. sports-tv from CAMRA (''Sports TV Terrestrial''); outdoor-drinking not tagged (small smoking veranda only); real-ale-specialist not tagged. No events (/whats-on 404; offers page generic). Deal lead not entered: ''25% off when you sign up'' (offers page title only, no terms). ''Evening Deal'' and ''Bottomless Brunch'' pages exist but their menus 404 (probably inactive). CAMRA puts it in ''Temple''.
