insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-holy-tavern', 'The Holy Tavern', '55 Britton Street, Clerkenwell, London EC1M 5UQ', 'Clerkenwell', 51.52177, -0.10402, 1996, array['historic', 'real-ale-specialist', 'food', 'dog-friendly', 'no-music-no-tv']::text[], 'A candlelit, wood-panelled tavern in a 1720 Clerkenwell merchant''s house, fitted out in 1996 to look like an 18th-century coffee house. Formerly the Jerusalem Tavern, St Peter''s Brewery''s only London pub, it was renamed the Holy Tavern in 2022. It still pours St Peter''s ales from taps set into the wall, alongside London craft keg, across a warren of tiny rooms and a mezzanine.', 'https://theholytavern.co.uk/', null, null, 'Independent', '{"0":[["12:00","21:30"]],"1":[["12:00","23:00"]],"2":[["12:00","23:00"]],"3":[["12:00","23:00"]],"4":[["12:00","23:00"]],"5":[["12:00","23:00"]],"6":[["12:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-holy-tavern', 'no', '[29 Sep 2026 research] RENAMED: formerly the Jerusalem Tavern (St Peter''s Brewery) until 2022; reopened 14 Aug 2026 after closure. St Peter''s did not renew its lease in 2022 and the pub reopened in March 2022 as The Holy Tavern, run by the building''s owners (freehold and leasehold held by individuals; CAMRA says the St Peter''s tie ''remains for the time being''). theholytavern.co.uk counted down to ''Doors Open 14th August 2026... opens once more''; CAMRA photos dated 2026-08-14, listing updated 22 Aug 2026; Untappd check-ins 22-25 Sep 2026, so trading now. No news story found explaining the mid-2026 closure. St Peter''s site has no pub page (/jerusalem-tavern/ 404). The older theholytavern.com (linked from Untappd and Pubs Galore) now redirects to a parked page. NO PRICES ONLINE: no menu on the site, Untappd venue unverified (no menu), nothing on pint-prices.com; TripAdvisor and Yelp unreadable. Vague reports: cask pints ''better value at £7.50ish'' (Pubs Galore 2025/26); ''pint of cask and half of keg £11.60'' (20 Aug 2025) - neither usable. Check Instagram/Facebook or in person. Southwark London Pale was a cask guest (Aug 2025 report; CAMRA lists Southwark as a changing LocAle brewery) - not entered. CAMRA: 3 changing casks (Southwark, St Peter''s), 0 regulars; London Beer Guide (Oct 2025): 4 handpumps, 10 keg taps. OPENED: 1996 = opened as a pub (re-creation of an 18th-century tavern); building is a merchant''s house dated 1719/1720; Grade II listing dates the shopfront terrace c.1825. HOURS: pub site (Sun 21:30); CAMRA says Sun 21:00. Food Mon-Sat 12-15 and 16-21, Sun 12-20 (CAMRA). no-music-no-tv inferred from CAMRA ''Quiet'' and old Pubs Galore data - check. Event lead not entered: ''Candlelit Tuesdays'' in winter (The Infatuation, Dec 2023, unconfirmed). Time Out (15 Sep 2026) mentions summer drinking at beer barrels outside (pavement only; outdoor-drinking not tagged). Access: step at entrance, toilets downstairs, no accessible toilet. contact@theholytavern.com; facebook.com/TheHolyTavern; instagram.com/theholytavern.
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('ye-olde-mitre', 'Ye Olde Mitre', '1 Ely Court, Ely Place, London EC1N 6SJ', 'Holborn', 51.51843, -0.10738, 1773, array['historic', 'real-ale-specialist', 'food', 'outdoor-drinking']::text[], 'A tiny, famously hard-to-find tavern in an alley between Hatton Garden and Ely Place, tracing its origins to 1546 and the Bishops of Ely; the current building dates from the 1770s. Its wood-panelled little rooms include the stump of a cherry tree Elizabeth I is said to have danced around, and it''s known for well-kept cask ale from seven handpumps, a scrumpy cider and toasties and pork pies.', 'https://www.yeoldemitreholborn.co.uk/', 'https://www.yeoldemitreholborn.co.uk/drink', 'https://www.yeoldemitreholborn.co.uk/food/menus', 'Fuller''s', '{"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","23:00"]],"6":[["11:00","21:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('ye-olde-mitre', 'partial', '[29 Sep 2026 research] New pub. Fuller''s (manager Judith). NO CURRENT DRAUGHT PRICES ONLINE: the Fuller''s site has no priced drinks list; the pub''s Untappd for Business ''Draught range'' menu (updated 21 Sep 2026) is unpriced and needs headless Chromium to read. The only priced file is the wine/bottle PDF created 22 Feb 2023, still linked from /drink: Belgian bottles entered with Date seen 2023-02-22 (sizes as listed, 330ml), likely stale (its toasties were £5-£6.50 vs £8.95-£9.95 on today''s Tenkites menu). Same PDF: wines and ''Spring Tipples'' cocktails (Negroni Highball £8 etc.), not entered. Community: Asahi £7.35 (London Pub Map, 18 Apr 2024, date from X post ID). Iron Pier Milk Stout £6.10 cask (allthepubs blog, visit 14 Jun 2023) is a past guest - not entered. Not on pint-prices.com. Cask guests rotate; ''Coming next'' on Untappd: Fat Cat Tom Cat, Pheasantry Copper Pheasant, Camerons Thirst Blood, Orkney Sunstone, Thornbridge Green Mountain; craft Wimbledon Pale; ciders Broadoak Perry, Harry''s Scrummage, Sandford Devon Scrumpy, Thistly Cross Whisky Cask, Westons Old Rosie. Pub site: ''seven real ales... minimum of 3 guest ales... real scrumpy cider''. DEAL NOT ENTERED: CAMRA member 20% off real ale (a £6.10 pint came to £4.92) per a Jun 2023 blog visit - not confirmed current. HOURS: pub site Mon-Fri 11-23, Sat 11-21, Sun closed; Untappd Sat 11-19; older sources say closed weekends; JSON-LD holds food times (ignore). Food Mon-Fri 12-21:30, Sat 12-16; toasties to 17:00. OPENED: 1773 = current building (Historic England c.1773); the pub claims 1546 (built for the Bishops of Ely''s servants). Grade II; CAMRA National Inventory; SPBW London Pub of the Year 2013 and 2019. Dog policy unclear (site: assistance dogs welcome; Untappd: pet friendly) - not tagged. Widely described as no-music/no-TV but unconfirmed - not tagged. outdoor-drinking = ''Outside seating'' and covered smoking area. AREA: Holborn (OSM ''Hatton Garden, Holborn''; domain yeoldemitreholborn). Tenkites food menu API: /api/tenkites?menuId=yeoldemitre05. yeoldemitre.ec1@fullers.co.uk.
