insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-craft-beer-co-clerkenwell', 'The Craft Beer Co. Clerkenwell', '82 Leather Lane, Clerkenwell, London EC1N 7TR', 'Clerkenwell', 51.52123, -0.10971, null, array['historic', 'real-ale-specialist', 'craft-beer', 'victorian-interior', 'food', 'quiz-night']::text[], 'A mid-19th-century Grade II-listed corner pub on Leather Lane that became the first Craft Beer Co. in 2011. Under its ornate mirrored ceiling and chandelier it pours 16 cask and 21 keg lines of rotating independent beer, with 200-plus bottles and cans, bar snacks and an upstairs lounge.', 'https://www.thecraftbeerco.com/clerkenwell', 'https://docs.google.com/presentation/d/1EC2uRezUE6Tut_vY0UnLnMjFk7rzxUPQpV-gpNo5CQ4/edit', 'https://docs.google.com/presentation/d/1xN4qgPfWVSxsspd06hfDFzvub-dna86_WMcdnDksY9Y/edit', 'The Craft Beer Co.', '{"1":[["12:00","23:00"]],"2":[["12:00","23:00"]],"3":[["12:00","23:00"]],"4":[["12:00","23:00"]],"5":[["12:00","23:00"]],"6":[["12:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-craft-beer-co-clerkenwell', 'yes', '[29 Sep 2026 research] New pub. The Craft Beer Company (family business founded 2011; GM Shane). Its first pub, opened mid-2011 (site says July, a press quote says June); building mid-19th century, Grade II, CAMRA Real Heritage Pub. OPENED left blank (no exact building year; 2011 is when it became Craft Beer Co.). PRICES: live Google Slides decks linked from the branch page - ''Today''s Draught'' (https://docs.google.com/presentation/d/1EC2uRezUE6Tut_vY0UnLnMjFk7rzxUPQpV-gpNo5CQ4/edit) and ''Menu'' (bottles, wine, spirits, snacks: https://docs.google.com/presentation/d/1xN4qgPfWVSxsspd06hfDFzvub-dna86_WMcdnDksY9Y/edit); re-scrape via /export/txt or /export/pdf; no ''last updated'' date in the decks. All draught lines rotate (house kegs less often), so re-scrape before relying on them. Measures follow the deck''s column headers (pint for cask and house keg; 2/3 or 1/2 for guests). Skipped: 1/3-only lines (Radio City x Vibrant Forest Gluttony 8.4% £7.15; Siren High Definition 10% £10.60), Cascade Sang Rouge 750ml £54.60 (over £30), and 11 priced sharing bottles with blank names in the export (£9.50-£55; check in person). Cask pints £5.90-£6.10, cheaper than the Holborn/Covent Garden branch. Wine from £6.70/125ml; Prosecco £8.95/125ml; spirits from £4.90/25ml. Deal: 33% off most bottles/cans to take away (Menu deck, ''ask at the bar''). QUIZ: Tuesday, Compleat Quiz; 19:30 per WhatPub and Pubquizzers, 19:00 per the operator''s 2019/2025 listings - confirm. No other events. Food: branch page mentions platters, pies and scotch eggs but the current Menu deck lists only crisps £1.75, nuts £2.75, biltong/chorizo £3 (food tag kept for snacks; check). Not tagged: dog-friendly, sports-tv, live-music (no source). AREA: Clerkenwell (operator); OSM and WhatPub say Hatton Garden/Holborn. PHONE: 020 7671 0906 (branch page); Pubquizzers 020 7404 7049 (older). Coordinates from OSM. Access: ramp on request; step-free WC not adapted. clerkenwell@thecraftbeerco.com; facebook.com/craftbeercoEC1.
