insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('jamaica-wine-house', 'Jamaica Wine House', 'St Michael''s Alley, Cornhill, London EC3V 9DS', 'City', 51.5129497, -0.0856603, 1869, array['historic', 'victorian-interior', 'cellar-bar', 'outdoor-drinking']::text[], 'Hidden in a medieval alley off Cornhill, ''the Jampot'' stands on the site of London''s first coffee house (1652) and has traded as a pub since 1869. The ground-floor bar is a wood-panelled Victorian room divided by mahogany screens, pouring Shepherd Neame''s Kentish ales to City workers who spill into the alley, with a new basement cocktail bar, the Jamaica Clubhouse.', 'https://www.jamaicawinehouse.co.uk/', 'https://snsites.co.uk/sites/default/files/2026-07/Jamaica%20Wine%20House%20Drinks%20Menu.pdf', null, 'Shepherd Neame', '{"1":[["11:00","22:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","23:00"]],"6":[["11:00","21:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('jamaica-wine-house', 'yes', '[29 Sep 2026 research] New pub. Shepherd Neame (managed directly by the brewer). Known as ''the Jampot''. PRICES: the pub''s own drinks menu PDF on snsites.co.uk (created 10 Jul 2026, ''prices may be subject to change''), linked from /drinks. It gives one price per draught with NO measure stated: recorded as pints (assumption; check in person). Bottle sizes not stated. Spritzes £11-£13; Clubhouse cocktails £13-£14 (separate PDF, Sep 2026); house wine from £7.20 (medium glass), bottles from £26.50; spirits mostly £5.65-£6.30; 2026 wine list PDF not parsed. CAMRA regulars Master Brew and Spitfire + 1 guest (fits the PDF). METHOD (reusable for Shepherd Neame): pub pages need headless Chromium (Cloudflare), but the snsites.co.uk PDFs download with plain curl; pdftotext -layout; pdfinfo for the date. JSON-LD gives geo, phone and hours. Sister City pubs on the same platform: Cock & Woolpack, East India Arms, Old Dr Butlers Head, Samuel Pepys, Hoop and Grapes. HOURS: pub site; SATURDAY OPENING NEW from 26 Sep 2026 (CAMRA still says Sat closed); Sunday closed. NEW BASEMENT: the Jamaica Clubhouse cocktail bar opened 22 Sep 2026 (40 seated / 80 standing), replacing Todd''s Wine Bar (still named in the JSON-LD). EVENTS NOT ENTERED: ''Cellar Sessions'' in the Clubhouse (live acoustic music, tastings, quizzes, cocktail workshops) with no dates published - check Facebook/Instagram @jamaicawinehouse before adding events or live-music / quiz-night tags. No deals (Shepherd Neame Birthday Club is a chain sign-up). FOOD: CAMRA says lunchtime and evening meals, but the site has no food menu; Beer Guild (29 Sep 2026) reports Honest Burgers ordered by QR code; bar snacks on the drinks PDF; food tag not added - check. OPENED: 1869 = began trading as the Jamaica Wine House (pub site); CAMRA says rebuilt 1885 by Banister Fletcher. First coffee house 1652 (site) or 1654 (CAMRA). Grade II. Coordinates from the pub site JSON-LD (CAMRA''s are slightly different).
