insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-viaduct-tavern', 'The Viaduct Tavern', '126 Newgate Street, London EC1A 7AA', 'City', 51.51629, -0.10169, 1874, array['historic', 'victorian-interior', 'food', 'dog-friendly']::text[], 'A late-Victorian gin palace of 1874-75 opposite the Old Bailey, refitted around 1900 with one of London''s finest pub interiors: etched and gilded glass, an ornate ceiling and three paintings of women signed ''Hal''. The cellars are said to be old debtors'' cells. Today it''s a Fuller''s pub with cask ales, gins, toasties and pies, popular with City workers.', 'https://www.viaducttavern.co.uk/', 'https://www.viaducttavern.co.uk/-/media/sites/pubs-and-hotels/v/the-viaduct-tavern-_-p121/files/global-menu-files/viaduct-tavern-drinks-menu.pdf', 'https://www.viaducttavern.co.uk/food/menus', 'Fuller''s', '{"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","23:00"]],"6":[["12:00","20:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-viaduct-tavern', 'partial', '[29 Sep 2026 research] New pub. Fuller''s (leasehold; CAMRA lists Norges Bank as freeholder); formerly Ind Coope / Nicholson''s. Trading (site live with a Christmas 2026 page, manager Kieran; Untappd check-ins 23 and 26 Sep 2026). PRICES: the only priced source is the pub''s own drinks PDF linked from /drink, created 2 Sep 2023 and last edited 15 Sep 2023 (PDF metadata), so Date seen = 2023-09-15 and every row is flagged as a 2023 menu. Prices are probably ~3 years stale (London Pride £5.95 looks low for the City in 2026). Draught measure not stated (pint assumed). Same PDF: wine 175ml from £6.50; cocktails £8.50-£13; gin 25ml £5.25-£8.75; Gin Tasting Board unpriced (not a deal). RANGE DRIFT: 2023 PDF had Oliver''s Island; CAMRA 2026 regulars are London Pride and ESB + 2 changing; Untappd Sep 2026 shows Gale''s HSB, Vocation Bread & Butter (cask) and Tiny Rebel Rebel IPA (draught) - added unpriced. Keg range not checked since 2023. Pub site: ''four world class cask ales and up to eight different beers on draught''. Community: TripAdvisor 1 Feb 2024 ''£32.50 for 2 double gin and tonics'' (not entered). Not on pint-prices.com. HOURS: visible table on the site (schema.org openingHours holds food hours + a placeholder Su 00:00). Sunday closed; the 2023 PDF offers private hire on Sat/Sun. Food Mon-Fri 12-21, Sat 12-19. No events (Fuller''s events feed empty; Christmas bookings only) and no deals. OPENED: 1874 (built 1874-75; interior 1898-1900 by Arthur Dixon). Grade II; CAMRA National Inventory three stars. Cellars said to be debtors'' cells, shown at quiet times (not a cellar bar). Access: CAMRA says step at entrance, narrow steps to toilets, no accessible toilet. Fuller''s events feed: /api/events/feed?pubId=F13D5BB7302B464C89E93C60688A8F28 (dates DD/MM/YYYY). viaduct@fullers.co.uk. Check in person: current pint prices and Sunday opening.
