insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('ye-grapes', 'Ye Grapes', '16 Shepherd Market, Mayfair, London W1J 7QQ', 'Mayfair', 51.50663, -0.1463, 1882, array['historic', 'food', 'outdoor-drinking']::text[], 'A corner pub in the village-like enclave of Shepherd Market, first licensed in 1742 as a coffee house and rebuilt in 1882. Its high-ceilinged, bare-boarded bar has a hunting theme, taxidermy and a real fire, with five handpumped ales and a wide keg range, a Thai restaurant upstairs and drinkers spilling outside.', 'https://yegrapesmayfair.co.uk/', 'https://yegrapesmayfair.co.uk/beer-list/', 'https://yegrapesmayfair.co.uk/menu/', 'Shannon Pubs', '{"0":[["12:00","22:30"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","23:00"]],"6":[["11:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('ye-grapes', 'no', '[30 Sep 2026 research] New pub. Shannon Pubs (small London pubco; sister pub The Chequers Tavern, St James''s; CAMRA ''Operator: Shannon Pubs''; operator since at least Jan 2020; briefly Greene King c.2019 - the house bitter is still a GK/Hardys & Hansons beer). Trading: Untappd check-ins 23-30 Sep 2026. NO DRINK PRICES ONLINE: beer list has names only; online PDFs are food (Thai and English) and a wine list hosted on thechequerstavern.co.uk (download reset; retry - may have wine prices). Not on pint-prices.com (nearby Kings Arms, 2 Shepherd Market, has London Pilsner £6.70 there - context only). No dated 2025-26 community prices (Pubs Galore Scrum Down £4.90 Mar 2019 under GK - too old). Facebook https://www.facebook.com/p/Ye-Grapes-100063457902972/ not checked. Check prices in person. Range: CAMRA says 5 handpumps, a house best bitter plus changing Adnams, St Austell and Timothy Taylor Golden Best; website list last updated Mar 2025, so rotating ales may have changed. OPENED: 1882 = current building; licensed 1742 as the Market Coffee House, renamed the Grapes 1782, Bunch of Grapes 1827. Grade II (1236202). Hours: pub site and CAMRA agree. Kitchen Mon-Fri 12-15:30 and 17-21:30, Sat-Sun 12-21. Food: pub classics £12.95-£18.95, Thai mains £13.95-£16.95. NOT ENTERED AS A DEAL (food only): Mon-Fri 12-15 set lunch, 2 courses £15.50-£17.50 (PDF Feb 2025, still linked). No events. PHONE: 020 7493 4216 (pub site, CAMRA, used); UseYourLocal''s older 020 7491 0910. Tags: outdoor-drinking = roped-off standing area outside. Not tagged: sports-tv (UseYourLocal only, unconfirmed), victorian-interior, dog-friendly. /menu/ is behind a bot check for curl; use the WP REST API (/wp-json/wp/v2/pages/44) or headless Chromium. Email yegrapesmayfair@yahoo.com. Operator site https://shannon-pubs.com/.
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-golden-eagle', 'The Golden Eagle', '59 Marylebone Lane, Marylebone, London W1U 2NY', 'Marylebone', 51.51767, -0.15082, 1890, array['historic', 'victorian-interior', 'real-ale-specialist', 'live-music', 'sing-along', 'dog-friendly']::text[], 'A tiny single-room Victorian corner pub on Marylebone Lane, first licensed in 1842 and rebuilt in 1890, with a spectacular etched-mirror bar-back, stained glass and red banquettes. The same family has run it for more than 30 years; it serves cask ales and is famous for old-school piano sing-alongs three nights a week.', null, null, null, 'Independent', '{"1":[["12:00","22:30"]],"2":[["12:00","22:30"]],"3":[["12:00","22:30"]],"4":[["12:00","22:30"]],"5":[["12:00","23:00"]],"6":[["12:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-golden-eagle', 'no', '[30 Sep 2026 research] New pub. Independent free house, family-run by landlady Gina Vernon (CAMRA: 35 years for the family in 2026; son Jack Plows a partner per a 2020 article). Trading: Untappd check-ins 10-30 Sep 2026; CAMRA updated 19 Jul 2026 (last surveyed Feb 2020). NO WEBSITE, NO PRICES ONLINE. Only 2026 price: Guinness £6.80 (pintmap, c. Apr 2026). Older community prices not entered as drinks: guest cask ale (unnamed) £5.70 (Tripadvisor review Dec 2024; Dec 2023 review £5.60 for a Christmas ale; quotes via an AI summary, check) and Portobello Westway Pale Ale £5.50 (past guest, Pubs Galore Jan 2024). Cask probably higher now - check in person. Guest casks rotate (e.g. 8 Sail, Oakham, Three Acre). HOURS CONFLICT: CAMRA Mon-Thu 12-22:30 (used), Tripadvisor 23:00; CAMRA''s piano night to 23:00 suggests Tue and Thu run to 23:00. Londonist''s ''Mon-Sat 11-23, Sun 12-19'' is out of date. Sunday closed. EVENT: piano sing-along Tue, Thu, Fri 20:30-23:00 (CAMRA 2026, Marylebone Village 2020); Londonist''s ''Saturday evenings'' is outdated. OPENED: 1890 = current building; first licensed 1842. CAMRA one-star heritage interior. No food (Pubs Galore: no hot food; Londonist mentions a limited menu) - food tag not added. Step-free access but no disabled WC (CAMRA).
insert into public.drinks (pub_id, name, category, measure, volume_ml, current_price, source, source_url, last_updated_at) values ('the-golden-eagle', 'Guinness', 'Stout', 'pint', null, 6.80, 'seed', null, now() - interval '28 days') on conflict (pub_id, name_normalized, measure) do nothing;
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-barley-mow-marylebone', 'The Barley Mow', '8 Dorset Street, London W1U 6QW', 'Marylebone', 51.5197, -0.15566, 1791, array['historic', 'victorian-interior', 'real-ale-specialist', 'food', 'quiz-night', 'live-music', 'sing-along', 'sports-tv', 'outdoor-drinking']::text[], 'Built in 1791 and said to be Marylebone''s oldest pub, this is one of central London''s last independent free houses. Its listed interior keeps two rare Victorian drinking booths at the bar, and it feels like a village local, with a famous Tuesday quiz, a darts league, pies and a wide range of cask ales.', 'https://thebarleymowmarylebone.com/', 'https://thebarleymowmarylebone.com/beer-%26-cider', 'https://thebarleymowmarylebone.com/food', 'Independent', '{"0":[["12:00","22:00"]],"1":[["12:00","23:00"]],"2":[["12:00","23:00"]],"3":[["12:00","23:00"]],"4":[["12:00","23:00"]],"5":[["12:00","23:00"]],"6":[["12:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-barley-mow-marylebone', 'yes', '[30 Sep 2026 research] New pub. Independent free house (pub site: ''independently owned Barley Mow in Marylebone, not to be confused with the bar in Mayfair which is part of Cubitt House Group'' - the Cubitt House Barley Mow is at 82 Duke St). Pub ID the-barley-mow-marylebone to avoid a clash. PRICES: the pub''s own beer & cider page (GoDaddy site, plain curl works), seen 30 Sep 2026. The page DOES NOT STATE MEASURES: draught and cask recorded as pints (assumption; the page says ''come in for a pint''); bottle sizes not stated. Wine priced by glass/carafe/bottle, e.g. house Pinot Grigio £4.70/£6.65/£9.40/£28; Prosecco £8 glass, £38 bottle. Cask ales rotate (named breweries incl. Adnams, Animal, Black Sheep, Harvey''s, Sharp''s, Timothy Taylor, Tring, Vale, XT); CAMRA: Landlord and Doom Bar regular + 3 changing. Two guest kegs change monthly; the page stops at August 2026 (Aspall Draught Cyder) - no current guests entered. Grolsch (in the Monday deal) is not on the draught list - probably stale. DEAL: Monday Madness pie + pint/small wine/soft drink £16.50 (same as a pie alone), 12-15 and 18-21. EVENTS: weekly Tue quiz 19:30 and Sat live music 20:00, plus dated one-offs from 1 Oct 2026. Not entered: Alex Beckett Darts League (32 teams, fully subscribed; board not public Mon/Tue nights or all day Sat; board hire £15/hr) and the annual Christmas charity quiz for Shelter (date TBC; raised £5,200 in 2025). CLOSURE: Sat 17 Oct 2026 closed from 17:00 for a private event. Kitchen Mon-Tue 12-15 and 18-21, Wed-Sat 12-15, Sun 12-16; bar snacks Mon-Fri; pie menu only at weekends. OPENED: 1791 (built; opened to the public 1793 per the pub site). LISTING: Grade II (Historic England 1381201); the pub site''s ''Grade II*'' is wrong. CAMRA National Inventory three stars (two Victorian drinking booths, matchboard panelling, rear snug). sports-tv and outdoor-drinking (pavement tables with heaters) per CAMRA. Email thebarleymoww1@gmail.com; Instagram @thebarleymow_marylebone.
