insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-nags-head-belgravia', 'The Nag''s Head', '53 Kinnerton Street, Belgravia, London SW1X 8ED', 'Belgravia', 51.501176, -0.156934, null, array['historic', 'dog-friendly', 'live-music']::text[], 'A tiny early-Victorian beer house on a Belgravia mews street, famous for its house rules: no mobile phones, coats on the hooks and a minimum spend for cards. It has a very low bar counter with antique Chelsea-pottery handpumps and three split-level rooms crammed with memorabilia and vintage slot machines, and has been run by the same eccentric landlord for decades.', null, null, null, 'Independent', '{"0":[["12:00","22:30"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","23:00"]],"6":[["11:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-nags-head-belgravia', 'no', '[30 Sep 2026 research] New pub. Independent free house run by Kevin Moran (CAMRA, updated 24 Aug 2026; fascia ''Kevin Moran''s Nags Head''). Trading (Tripadvisor reviews Aug-Sep 2026). NO WEBSITE, NO PRICES ONLINE. COMMUNITY PRICES (not entered as drinks because the beer isn''t named): ''£8.50... too expensive'' for an unnamed beer (Tripadvisor, May 2025, most recent priced report; probably Ghost Ship or Southwold); ''All beers are £8'' (Pubs Galore, 20 Feb 2024). A Dec 2025 blog says ''London''s most expensive pint just got more expensive'' (no figure), so prices are likely above £8.50 now. Ghost Ship £6.00 (2022) too old. Dec 2024: ''26 quid for a pint and a half plus bottle of still water'' (not itemisable). Crisps £2.50 (May 2025). Not entered: Bitburger (seen Feb 2024, not confirmed now), a cider (Sep 2026 review, brand not given), and CAMRA''s one changing Adnams beer. HOUSE RULES: no mobile phones, no children, coats on hooks; staff discourage small groups at large tables. PAYMENT: card only over £15 (reports 2022 and Feb 2024; an Aug 2024 blog says ''no cards (or a high minimum)'') - check. EVENT NOT ENTERED: live music on the first Sunday of each month at 14:30 (CAMRA; not weekly, no dates published). No quiz or sports TV. FOOD CONFLICT: CAMRA lists evening meals, Pubs Galore hot food, but a Sep 2026 reviewer says it ''does not serve food'' - food tag not added. Not no-music-no-tv (Sinatra in the background per a review). outdoor-drinking not tagged (pavement standing only). OPENED left blank: ''early Victorian beer house'' (CAMRA), layout on 1906 plans, Ind Coope tenancy 1929-73, refurbished 1975; not listed. CAMRA: interior of local historic interest; 150-year-old pewter beer engine with Chelsea Pottery handpulls. Landlord start year conflicts (1994 CAMRA vs 1982 Londonist). Coordinates from CAMRA (pint-prices agrees). Hours: CAMRA (Tripadvisor''s Wed 09:00 open looks wrong). Pub ID the-nags-head-belgravia to avoid clashes with other Nag''s Heads.
insert into public.drinks (pub_id, name, category, measure, volume_ml, current_price, source, source_url, last_updated_at) values ('the-nags-head-belgravia', 'Adnams Dry Hopped Lager', 'Lager', 'pint', null, 7.00, 'seed', null, now() - interval '3 days') on conflict (pub_id, name_normalized, measure) do nothing;
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-star-tavern', 'The Star Tavern', '6 Belgrave Mews West, Belgravia, London SW1X 8HT', 'Belgravia', 51.49844, -0.15586, 1848, array['historic', 'victorian-interior', 'real-ale-specialist', 'food', 'dog-friendly']::text[], 'A Grade II-listed 19th-century mews pub hidden off Belgrave Square, one of only five pubs in every edition of CAMRA''s Good Beer Guide and famous as the 1960s haunt where the Great Train Robbery was planned. Inside are snug wood-panelled rooms, a Victorian bar-back, real fires and an upstairs ''Library'' bar, with mostly Fuller''s cask ales.', 'https://www.star-tavern-belgravia.co.uk/', 'https://www.star-tavern-belgravia.co.uk/drink', 'https://www.star-tavern-belgravia.co.uk/food/menus', 'Fuller''s', '{"0":[["12:00","21:00"]],"1":[["12:00","22:00"]],"2":[["12:00","23:00"]],"3":[["12:00","23:00"]],"4":[["12:00","23:00"]],"5":[["12:00","23:00"]],"6":[["11:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-star-tavern', 'no', '[30 Sep 2026 research] New pub. Fuller''s (leasehold; freehold Ineos London Property Holdings Ltd; manager Chris). Trading (site live, WhatPub updated 17 Jul 2026, Untappd check-ins to 22 Sep 2026). OPENED 1848 - FLAG: CAMRA WhatPub cites a licence application in the Morning Advertiser of 13 Mar 1848; a Feb 2025 blog (propupthebar) says 1864; Wikipedia says only ''early to mid-19th century''. 1848 used (primary source cited), check. NO DRINK PRICES FOUND: /drink has only an unpriced wine-list PDF; Ten Kites menus (startavern02-09) are food only (e.g. cheeseburger £18.95); Untappd venue unverified (no menu); WhatPub no prices; pint-prices.com search not resolved (POST form - try headless Chromium); Guinness Map and Google review photos not tried. Check in person. Range: ''normally four or five'' cask ales (mostly Fuller''s) plus guests on a ''Now Pouring'' board; no lager or cider brands named anywhere. Phone ahead for a specific beer; the range may be cut back in hot weather (WhatPub). HOURS: visible table (schema.org openingHours holds food times: Mon-Fri 12-15 and 17-21, Sat 11-21, Sun 12-20). No events (Fuller''s events feed empty, pubId F99F0C04C9D34628BD7F90A4BB50E722); board games; no quiz, music or sports TV found. No deals. NOT outdoor-drinking: WhatPub says drinks must NOT be taken outside. Grade II (1357183, 1987); CAMRA National Inventory one star (Victorian bar counter, mirrored bar-back with ''Family Wine And / Spirit Stores'' lettering). Awards: CAMRA West London Pub of the Year 2017; Golden Award 2021. startavern.sw1@fullers.co.uk.
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-kings-arms-waterloo', 'The King''s Arms', '25 Roupell Street, London SE1 8TB', 'Waterloo', 51.504466, -0.109073, null, array['historic', 'real-ale-specialist', 'food', 'quiz-night', 'outdoor-drinking']::text[], 'A Grade II-listed early-19th-century corner pub on Roupell Street, a terrace of old cottages often used for filming. Two small bare-boarded front bars share a horseshoe counter with eight handpumps of changing cask ales, and a big skylit back room full of bric-a-brac hosts Thai food from Kanchana''s Kitchen and the Sunday quiz.', 'https://thekingsarmslondon.co.uk/', 'https://thekingsarmslondon.co.uk/wp-content/uploads/sites/7/2026/07/The-Kings-Arms-Wine-Menu.pdf', 'https://thekingsarmslondon.co.uk/wp-content/uploads/sites/7/2026/03/KANCHANAS-KITCHEN-MENU-2026.pdf', 'Windmill Taverns', '{"0":[["12:00","22:30"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","23:00"]],"6":[["11:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-kings-arms-waterloo', 'partial', '[30 Sep 2026 research] New pub. Windmill Taverns (Mc & Sons group: Mc & Sons Borough/Vauxhall, Molly Mcs, The Ring; thekingsarms@windmilltaverns.com). Trading (site content Jul-Aug 2026; Untappd check-ins 29-30 Sep 2026). NO BEER PRICES ONLINE: only a wine PDF (Jul 2026: house white £7.40/175ml, reds and rosé £8-£8.50/175ml, bottles £28-£30, Prosecco £7.50/125ml, Moët £90) and Thai food menus; WP media library has no beer list. Only beer price: VOG Dark mild £5.90 on a 1 Mar 2024 visit (pubsandbeer; a past guest, stale - not entered). Not on pint-prices.com (the ''Kings Arms SE11 4XD'' there is a different pub) or the Guinness Map. Check prices in person. Cask range changes constantly: 8 handpumps (CAMRA: 5 changing + 3 regular); ~10 keg taps and ~10 bottles/cans (London Beer Guide); keg line-up unknown apart from DEYA Boost. PRIVATE-HIRE PACKAGES (not deals; brochure Aug 2026): 10 bottles of beer (Corona, Budweiser, Daura, Peroni, Peroni 0%) £55; 3 bottles of house wine £80; Prosecco reception (2 glasses each) £13 per person. EVENT LEAD not entered: beer masterclass/tasting with in-house cicerone Chris, 6 beers, £35 per person, by advance booking. HOURS: pub site gives only opening times (''11 - Late'', Sun ''12 - Late''); closing times from CAMRA and Londonist. No drinking-up time: closes exactly on time (CAMRA). Kitchen (Kanchana''s Kitchen, a separate business) Mon-Fri 12-15 and 17-22, Sat 13-22, Sun 13-21:30 (CAMRA says Sunday food to 18:00 - older). Card payment only. No table bookings in the pub; upstairs rooms Roupell Suite (30) and Bonsie''s (15) can be hired. CAMRA SE1 District Pub of the Year 2024. OPENED left blank (early-to-mid 19th century, no exact year); Grade II; CAMRA regional-importance interior. Pub ID the-kings-arms-waterloo to avoid clashes. Sister-site drinks PDFs (e.g. Molly Mcs) are a possible group pricing lead.
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-george-inn', 'The George Inn', '75-77 Borough High Street, Southwark, London SE1 1NH', 'Borough', 51.504149, -0.089992, 1676, array['historic', 'beer-garden', 'outdoor-drinking', 'food', 'dog-friendly', 'sports-tv', 'live-music']::text[], 'London''s last surviving galleried coaching inn, rebuilt in 1676 after a fire, Grade I listed and owned by the National Trust since 1937. Warped timber galleries overlook a large cobbled courtyard with outdoor seating, and inside is a warren of small rooms including the Parliament Bar with its old woodwork and one-handed clock. It''s a Greene King pub serving cask ales and food.', 'https://www.greeneking.co.uk/pubs/greater-london/george-southwark', 'https://www.greeneking.co.uk/pubs/greater-london/george-southwark/menu', 'https://www.greeneking.co.uk/pubs/greater-london/george-southwark/menu', 'Greene King (building owned by the National Trust)', '{"0":[["11:00","23:00"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","00:00"]],"5":[["11:00","00:00"]],"6":[["11:00","00:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-george-inn', 'partial', '[30 Sep 2026 research] New pub. Operator Greene King (managed; GK pub ID 7781, 7781@greeneking.co.uk; GK brands it ''George, Southwark'', URL slug /george-southwark - /george-inn is a 404). BUILDING OWNED BY THE NATIONAL TRUST since 1937 and leased to Greene King (NT and CAMRA text); CAMRA''s ''Freehold owner: Greene King'' field conflicts - go with NT. NO OFFICIAL BEER PRICES: GK menu API (getmenus/7781) has wine and cocktails only; beer prices are app-only. Cocktails £12.50, spritzes £13, 0% cocktails £11, Prosecco for one £7.75, wine e.g. Pinot Grigio £7.20/£8.50/£10.80, bottle £30. Seven UNDATED pint-prices.com prices entered as Community. ESTRELLA CONFLICT: three duplicate listings show £7.40 (used), £7.30 and £6.00. Guinness Map no page; Tripadvisor and Good Beer Good Pubs unreachable. Older Untappd ''popular drinks'' (Brentwood Common Sense, Southwark Five Hop Amber IPA) undated - not entered. EVENTS: weekly Thu and Fri live music 19:00-21:00 (GK What''s On, next 1 and 2 Oct 2026). Not entered: live football (Sky Sports and TNT; no fixtures) and generic GK seasonal promos. Deals not entered: GK ''Accepts Matchday Discount'' (no terms) and app ''spin to win''. OPENED: 1676 = rebuild after the Southwark fire; an inn on the site from at least the 16th century; part demolished 1889. Grade I; CAMRA Real Heritage Pub. Upstairs Gallery Bar ''not always open'' (CAMRA). DON''T CONFUSE: Craft Union''s ''George Southwark'' (40 Tower Bridge Road) and ''The Coach House at the George'' (separate GK sports bar in the same courtyard). GK''s ''Waterside Pub'' facility is wrong. Access: 3 steps down, no accessible toilet. Instagram @georgeinn1676.
