insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-market-porter', 'The Market Porter', '9 Stoney Street, Borough Market, London SE1 9AA', 'Borough', 51.505363, -0.091301, null, array['historic', 'real-ale-specialist', 'food', 'sports-tv', 'outdoor-drinking', 'dog-friendly']::text[], 'A Victorian market pub on Stoney Street beside Borough Market, famous for its big rotating range of cask ales and for opening at 6am on weekdays for market workers. The busy S-shaped ground-floor bar spills onto the street, and a quieter upstairs dining room with its own bar overlooks the market.', 'https://themarketporter.co.uk/', 'https://themarketporter.co.uk/wp-content/uploads/2025/07/The-Market-Porter-Bar-Wine-List-July-25.pdf', 'https://themarketporter.co.uk/food-and-drink/', 'Market Taverns', '{"0":[["12:00","22:30"]],"1":[["06:00","09:00"],["10:00","23:00"]],"2":[["06:00","09:00"],["10:00","23:00"]],"3":[["06:00","09:00"],["10:00","23:00"]],"4":[["06:00","09:00"],["10:00","23:00"]],"5":[["06:00","09:00"],["10:00","23:00"]],"6":[["12:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-market-porter', 'partial', '[30 Sep 2026 research] New pub. Market Taverns (leasehold); freehold United St Saviours Charity. Trading (Untappd check-ins 30 Sep 2026; site updated Jul 2026). NO PINT PRICES ONLINE: no beer list on the site; Untappd venue unverified (no menu); pint-prices.com search 404; no prices in Tripadvisor/Londonist/Time Out snippets. Leads: Instagram @themarketporter or Facebook tap-board photos; in-person check. Range: 5 rotating + 2 regular cask ales (CAMRA), up to nine (Londonist). Wine list PDF Jul 2025 (still linked): e.g. house white £6.60/175ml, £25 bottle; Pinot Grigio £7.30/£28; Prosecco £7/125ml, £35 bottle. NOT DEALS (over £30, festive): Christmas 2026 buckets of 12 bottles (Corona, Heineken 0.0, Jubel Peach, Peroni, Peroni GF, Lucky Saint) £50; ciders (Rekorderlig, Bulmers) £65. Obsolete 2023 Christmas PDF bucket prices not used. DEALS: Fish & Chip Mondays £19 (Jul 2026 bar menu); CAMRA member 10% off cask (CAMRA). HOURS: Mon-Fri 06:00-09:00 then 10:00-23:00 (entered as two sessions); Sat 12-23; Sun 12-22:30. Londonist (2015) said the 6am slot served pre-booked breakfast - not confirmed now. Kitchen Mon-Sat 12-21:30, Sun 12-16:30; bar lunch menu Mon-Fri 12-17. Events: Sunday roast entered as a weekly food event (Fish & Chip Mondays is in Deals). No live music or quiz; sports TV (CAMRA), no fixtures. CARD ONLY, no cash (CAMRA). 12.5% service on food; optional £1 charity donation. Upstairs Dining Room 40 seated / 60 standing, private bar. OPENED left blank (no reliable date; site says ''one of the oldest and best Victorian pubs''). Asset of Community Value. Media list for new PDFs: /wp-json/wp/v2/media?per_page=100. hello@themarketporter.co.uk.
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-rake', 'The Rake', '14 Winchester Walk, Borough Market, London SE1 9AG', 'Borough', 51.5062294, -0.0906058, 2006, array['craft-beer', 'outdoor-drinking', 'dog-friendly']::text[], 'Opened by the Utobeer team in 2006 on the site of an old Victorian pub, The Rake is a tiny glass-roofed beer bar behind Borough Market that calls itself ''London''s original beer bar''. Most drinkers spill onto the decked outdoor area, and the constantly rotating taps, handpumps and around 100 bottles and cans are served in thirds, halves, two-thirds or pints.', 'https://www.utobeer.co.uk/the-rake', 'https://untappd.com/v/the-rake/20074?menu_id=133100', null, 'Utobeer', '{"0":[["12:00","22:00"]],"1":[["12:00","23:00"]],"2":[["12:00","23:00"]],"3":[["12:00","23:00"]],"4":[["12:00","23:00"]],"5":[["12:00","23:00"]],"6":[["11:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-rake', 'yes', '[30 Sep 2026 research] New pub. Utobeer (independent; also runs the Utobeer stall in Borough Market). Old domain rakebar.co.uk is dead; website https://www.utobeer.co.uk/the-rake (JS site, Cloudflare rate limit - use headless Chromium). PRICES: the bar''s own Tap Menu page links to its Untappd VERIFIED menus, so entered as Pub website: draught menu (menu_id 133100, updated 30 Sep 2026 21:34 UTC, 19 items, every draught sold in 1/3, 1/2, 2/3 and pint) and fridge menu (menu_id 207608, updated 30 Sep 2026, 80 items). All priced draught pints entered (£5-£25; US imports are mostly bought as thirds). Tap list rotates daily. From the fridge list I picked 17 representative bottles/cans (cheap to notable) and skipped the rest to keep the sheet readable. Over £30, not entered: Elderflower Lambicus £40 and Boon HORAL''s Oude Geuze Mega Blend £40 (750ml). Also £30 exactly and not picked: Equilibrium Cookies & Cream Pop, Grimm Dreams Come True, Boon Oude Schaarbeekse Kriek. Tegernseer Spezial (5.6%) in the Oktoberfest section has no price or format - not entered. CASK: London Beer Guide says 3-4 handpumps + c.10 keg; the five unnumbered items at the end of the draught menu (Mango cider, Weightless, Rauchbier, Nonetheless, Gatekeeper) are probably the handpump/cider lines (inference) - categories left as brewed style. EVENT LEAD: six RedWillow beers on at once on 30 Sep 2026 look like a showcase/tap takeover, but none was announced; check @rakebar. No events or deals published. Community: pint-prices.com HOUSE LAGER and BUDWEISER £6.30 (undated, neither on the current menu) - not entered. OPENED: 2006 (opened Sep 2006, first bar within Borough Market for 100 years, on the site of a 19th-century pub). No food menu online. Tags: dog-friendly and outdoor seating are self-reported on Untappd - verify. real-ale-specialist not added. therake@utobeer.co.uk; X @rakebar; bookings https://www.utobeer.co.uk/bookings. Address sometimes given as 14a Winchester Walk. Coordinates from Untappd structured data (OSM blocked).
