insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-royal-oak-borough', 'The Royal Oak', '44 Tabard Street, London SE1 4JU', 'Borough', 51.500122, -0.091444, null, array['historic', 'real-ale-specialist', 'food', 'dog-friendly', 'quiz-night', 'live-music', 'sports-tv']::text[], 'A Victorian brick corner pub on a quiet Borough backstreet near the site of Chaucer''s Tabard Inn, bought by Sussex brewer Harvey''s in 1997 as its first London pub and restored as a traditional city beer house. Two bare-boarded bars are split by a mahogany off-sales area, serving the full Harvey''s cask range, with Dark Mild a favourite.', 'https://www.royaloaklondon.co.uk/', 'https://www.royaloaklondon.co.uk/drinks', 'https://www.royaloaklondon.co.uk/food', 'Harvey''s', '{"0":[["12:00","21:00"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","23:00"]],"6":[["11:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-royal-oak-borough', 'partial', '[30 Sep 2026 research] New pub. Harvey''s (Harvey & Son (Lewes) Ltd); its first London pub, taken over 1997. Team: Mike, Boyd and the team. Trading (site footer 2026; CAMRA updated 30 Jul 2026; Untappd check-ins 27-28 Sep 2026). NO BEER PRICES ONLINE (pub site or Harvey''s). Community prices from pubsandbeer visit reports with their report dates; newest £6.30 Armada (Feb 2026). A Jan 2022 report of Mild ''£3 a pint on Mondays'' is old and unconfirmed - not a deal. Check prices in person or ask the pub (site invites ''drop us a line'' about what''s on tap). NOT ENTERED (only on the pub''s 2023 beer menu PDF, unpriced, not confirmed recently): Harvey''s IPA (cask), keg Pilsner, Wharf IPA, Black Stout, Gold Bier, bottles Imperial Extra Double Stout and Prince of Denmark; seasonal casks Georgian Dragon (Apr), Tom Paine (Jul), Lewes Castle Brown (Aug), Star of Eastbourne (Oct), Bonfire Boy (Nov), Christmas Ale (Dec). The site says it serves ''Harvey''s beers (cask and keg)''. DEAL NOT ENTERED (wine): ''3 for 2 Wine Thursdays'' - buy 2 large glasses, get the rest of the bottle free. Wine list Sept 2024: £5.60-£7.70/175ml, bottles £20-£28, Prosecco £6.30/125ml, Sussex Sparkler £48. EVENTS: Wednesday quiz (start time not found; Facebook events page blocked). Live music evenings and beer events are ''regular'' per the site but undated - not entered. Food: Mon none; Tue 17-21; Wed-Fri 12-15 and 17-21; Sat-Sun 12-20. OPENED left blank: landlord quoted ''1825'' (Jane Sketching, Sep 2026); Harvey''s and the pub say Victorian; London Pub Map ''mid-nineteenth century''. victorian-interior not tagged (CAMRA classes it as a restoration). outdoor-drinking not tagged (CAMRA ''limited garden seating'' vs OSM outdoor_seating=no). Function room ''The Harvey''s Room'' (CAMRA: ''John Harvey Room'') with pool, darts, big screen. SE London CAMRA Pub of the Year 2023 and 2025; Cask Marque. enquiries@royaloaklondon.co.uk; Instagram @royaloakborough. Pub ID the-royal-oak-borough to avoid clashes.
