insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-hoop-and-grapes', 'The Hoop and Grapes', '47 Aldgate High Street, London EC3N 1AL', 'Aldgate', 51.514256, -0.074181, null, array['historic', 'food', 'sports-tv', 'dog-friendly']::text[], 'A rare surviving late-17th-century timber-framed building on Aldgate High Street, with a leaning, jettied front and carved posts at the door; the Great Fire of 1666 stopped just short of the site. A wine merchant''s until about 1920, it''s now a cosy, low-ceilinged Nicholson''s pub serving pies and cask ale to City and Aldgate office workers.', 'https://www.nicholsonspubs.co.uk/restaurants/london/thehoopandgrapesaldgatelondon', 'https://www.nicholsonspubs.co.uk/restaurants/london/thehoopandgrapesaldgatelondon/drinks', 'https://www.nicholsonspubs.co.uk/restaurants/london/thehoopandgrapesaldgatelondon/foodmenu', 'Nicholson''s (Mitchells & Butlers)', '{"0":[["11:00","23:00"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","00:00"]],"6":[["11:00","00:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-hoop-and-grapes', 'yes', '[30 Sep 2026 research] New pub. Nicholson''s (Mitchells & Butlers), open and trading. Prices from Nicholson''s own data (seen 30 Sep 2026): draught from the order-at-table menu (canOrder 0 - browsable, not orderable), bottles/low-no also on the web drinks menu (identical; lastModified 30 Sep 2026). M&B IDs: brand 112, brand scalable 09b752ce-97c8-5b9b-ab92-6cb9b533561f, BunCode 74713 (verified on every response), outlet scalable ee37e796-c88f-515c-887a-63a8523ffdaa, sales area 7a5be62a-88fa-533b-88c0-2fd3f36b22f1, TradingEntity 1001536. Web drinks API: api-production.mbplc.io/webappbff/api/v1/menus/dynamic?id=1001536&idType=TradingEntity&websitePageUrlPath=drinks-menu1&salesChannel=12. Cask: only Nicholson''s Pale Ale and Landlord on the menu; CAMRA says 3 changing beers too - check. Not entered: Peroni bucket of 6 £33.15 (over £30); ''25% off when you sign up'' (offers page title only, no terms). Wine £7.35-£9.65; Prosecco £7.20 glass; cocktails £10.95-£12.95; 0% cocktails £6.95; spirits from £4.35; Pimm''s jug £29.50. OPENED left blank: late 17th c. (Historic England ''probably late C17''); Nicholson''s says it survived the 1666 fire; CAMRA''s ''11th century / inn since the 13th century'' refers to the site and is unverified. A wine merchant''s until c.1920 (CAMRA). Grade II*. HOURS: Nicholson''s and M&B API; CAMRA says Mon-Fri open 12:00 and Sat close 23:30. Food Mon-Fri 12-22, Sat 11-22, Sun 11-21 (CAMRA). Holidays (M&B API): 24 Dec 12-23; 25 Dec 12-17 (open); 26 Dec 12-23; 31 Dec 12-23; 1 Jan 2027 12-23. No events (/whats-on generic; Six Nations page is past). sports-tv and dog-friendly from CAMRA. AREA: new area Aldgate (City of London).
