insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('old-doctor-butlers-head', 'Old Doctor Butler''s Head', '2 Mason''s Avenue, London EC2V 5BT', 'City', 51.5156882, -0.0902844, 1610, array['historic', 'food', 'sports-tv', 'outdoor-drinking', 'dog-friendly']::text[], 'Tucked down a narrow alley off Coleman Street near Guildhall, this Shepherd Neame pub claims roots in 1610 and is named after Dr William Butler, James I''s physician, whose medicinal ale was sold only in taverns showing his head on the sign. It''s a dark, traditional City pub with Kentish cask ales, pub classics and a small upstairs restaurant, busy on weekday evenings and closed at weekends.', 'https://www.olddoctorbutlershead.co.uk/', null, 'https://www.olddoctorbutlershead.co.uk/menus', 'Shepherd Neame', '{"1":[["12:00","22:00"]],"2":[["12:00","22:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('old-doctor-butlers-head', 'partial', '[30 Sep 2026 research] New pub. Shepherd Neame managed house (olddoctorbutlers@shepherdneame.co.uk). Trading (2026 wine list created 11 Sep 2026; Untappd check-ins 10-30 Sep 2026). CLOSED TO THE PUBLIC SAT & SUN (whole pub hired out for private functions at weekends). NO BEER PRICES ONLINE: no /drinks page (404) and no drinks PDF on snsites.co.uk (guessed paths for every month 2025-09 to 2026-09 all 404; the same method works for Jamaica Wine House). /menus has the food menu (e.g. haddock & chips £19.75) and a 2026 wine list PDF (Prosecco £6.50 small glass / £34 bottle; house wines from £5.40 small, £28-£28.25 bottle). STALE COMMUNITY PRICE NOT ENTERED: Birra Moretti £6.40 from a London Pub Map review shown as ''3 years ago'' (c. 2023; useyourlocal) - Moretti is £8.20 at sister pub Jamaica Wine House in 2026. Sister-pub prices are context only. Check prices in person (Mon-Fri). OPENED 1610 = established (pub and CAMRA); the pub says the present building dates from just after the 1666 fire, but the Grade II listing says ''probably early C19, altered'' - flag. HOURS: Wed opening 11:00 (footer and CAMRA) vs 12:00 (JSON-LD). Food Mon-Fri 12:00-20:00. No public events: the upstairs function room hosts private parties, quizzes and karaoke; JSON-LD ''Live Music: true'' but no gigs listed (live-music not tagged); BT/TNT Sport shown, no fixtures. No deals (Shepherd Neame Birthday Club is chain-wide). Tags: dog-friendly rests only on a JSON-LD flag - check; outdoor-drinking = alley with beer barrels. ADDRESS: 2 Mason''s Avenue EC2V 5BT (pub and CAMRA); inapub gives EC2V 5BY. Darts upstairs. Facebook/Instagram not checked for events.
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-seven-stars', 'The Seven Stars', '53-54 Carey Street, London WC2A 2JB', 'Holborn', 51.51497, -0.11349, null, array['historic', 'victorian-interior', 'food', 'no-music-no-tv', 'outdoor-drinking']::text[], 'A tiny, much-loved free house behind the Royal Courts of Justice, dated 1602 on its frontage though probably built in the late 17th century, with a Victorian bar-back, legal film posters, a resident cat and famously steep stairs to the loos. Landlady Roxy Beaujolais has run it since 2001, serving Adnams cask ales and a daily-changing blackboard menu, with no music.', 'https://www.thesevenstars1602.co.uk/', null, null, 'Independent (Roxy Beaujolais)', '{"0":[["12:00","22:00"]],"1":[["12:00","23:00"]],"2":[["12:00","23:00"]],"3":[["12:00","23:00"]],"4":[["12:00","23:00"]],"5":[["12:00","23:00"]],"6":[["12:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-seven-stars', 'no', '[30 Sep 2026 research] New pub. Independent free house run by Roxy Beaujolais since 2001 (leaseholder Roxy Beaujolais Ltd; freehold Fuller Smith & Turner). Trading (Untappd check-ins 28 and 30 Sep 2026; Aug 2026 review). NO PRICES ONLINE: no drinks or food menu online (daily blackboard; no reservations). Only prices: two Guinness Map reviews of 6 Mar 2025, £6.30 and £6.00 (site average £6.15) - one row entered at £6.30; Guinness may no longer be stocked. Reviews only say prices are ''well below what you might expect''. pint-prices.com connection reset; Yelp/RestaurantGuru 503. Not entered: the 1 changing guest cask (CAMRA: typically Dark Star Hophead or Greene King IPA) and Adnams Southwold Bitter (''no longer pouring'' per CAMRA). OPENED left blank: ''1602'' on the frontage and website (London Encyclopaedia too) is a claim; Pevsner and CAMRA say the building probably dates from the 1680s, extended 1878. Grade II; CAMRA three-star interior; Asset of Community Value. HOURS: pub site and CAMRA; Londonist (c. Feb 2025) says Mon-Sat 12-22, Sun 12-21. Closed on holidays. Food Mon-Fri 12-21:30, Sat-Sun 13-21:30 (CAMRA). No events or deals; no music or fruit machines (house rule). Pavement awnings and heaters since 2021. ADDRESS: 53 (pub site) / 53-54 (OSM, used) / 51-54 (CAMRA) Carey Street. Resident cat The General. Roxy@RoxyBeaujolais.com. Guinness Map prices are in the page''s embedded JSON (curl the raw HTML).
