insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-fox-and-anchor', 'The Fox & Anchor', '115 Charterhouse Street, London EC1M 6AA', 'Farringdon', 51.52044, -0.10075, 1898, array['historic', 'food', 'sports-tv', 'dog-friendly']::text[], 'A Grade II-listed 1898 Smithfield Market pub with a Doulton-tiled Art Nouveau front, long and narrow with snugs at the back and hotel rooms upstairs. Run by Young''s, it opens at 7am on weekdays and is best known for its huge market-porter breakfast served with a pint of Guinness.', 'https://www.foxandanchor.com/', 'https://my.propcom.co.uk/data/media/pdf/Fox%20%26%20Anchor.pdf', 'https://www.foxandanchor.com/food-drink', 'Young''s', '{"0":[["08:30","22:00"]],"1":[["07:00","23:00"]],"2":[["07:00","23:00"]],"3":[["07:00","23:00"]],"4":[["07:00","23:00"]],"5":[["07:00","23:00"]],"6":[["08:30","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-fox-and-anchor', 'partial', '[30 Sep 2026 research] New pub. Young''s (foxandanchor@youngs.co.uk; Young''s since summer 2014 per Pubs And Beer). Pub with boutique hotel rooms. NO 2026 BEER PRICES ONLINE: WP media library (~400 items) has no drinks PDF; Propeller CDN PDFs are wine (created Feb 2026; glasses from £7.10/175ml, Prosecco £7.60/125ml, £38 bottle) and Spritz 2026 (spritzes £10-£12.50, 0% £8.50-£9.50) - no beer. A ''Cocktail Winter Menu 2026'' image was uploaded 14 Sep 2026, so a new drinks PDF may appear. Old Pubs And Beer prices (£5.15 Apr 2018 etc.) not used. Six handpumps; ''ask about our alcohol-free beers & cider'' (none named). Check prices in person on a weekday morning. DEAL: Fox''s City Breakfast incl. a pint of Guinness £30, breakfast Mon-Fri 07:00-12:00, Sat-Sun 08:30-12:00. EVENTS: Autumn Nations rugby screenings Nov 2026 entered as one-offs; Finals Weekend entered on Fri 27 Nov (site''s slot) with Sat/Sun matches in the description. Not entered: Christmas Eve (open 07:00-16:00) and New Year''s Eve (07:00-23:00) listings, ''Christmas Parties in Farringdon'' (booking promo) and ''December Sleepovers'' (hotel package); hotel offers (e.g. Eat & Sleep from £180). No October events listed; Young''s Day (17 Sep) past. HOURS: pub footer (schema.org openingHours blank). Food: breakfast Mon-Fri 07-12, Sat-Sun 08:30-12; lunch Mon-Sat 12-16; dinner Mon-Sat 16-21:30; Sunday roast 12-21. OPENED: 1898 (Latham Withall; Doulton facade by W. J. Neatby); Grade II. victorian-interior not tagged (the notable work is the exterior); real-ale-specialist not tagged. Private room ''Bar Next Door'' (formerly The Vestry). Dog House Rules PDF. Coordinates from OSM. Untappd venue 73895.
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-three-kings', 'The Three Kings', '7 Clerkenwell Close, London EC1R 0DY', 'Clerkenwell', 51.52331, -0.10581, 1871, array['historic', 'food']::text[], 'A curved, three-storey brick corner pub rebuilt in 1871, looking over St James''s Church and its churchyard in Clerkenwell. It has one bar with four handpumps for changing cask ales, some inter-war fittings and old brewery window panels, upstairs function rooms and a home-cooked pub menu.', 'https://www.thethreekings.london/', 'https://www.thethreekings.london/drinks', 'https://www.thethreekings.london/food', 'Stonegate (tenanted)', '{"0":[["12:00","21:00"]],"1":[["12:00","23:00"]],"2":[["12:00","23:00"]],"3":[["12:00","23:00"]],"4":[["12:00","23:00"]],"5":[["12:00","23:00"]],"6":[["12:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-three-kings', 'no', '[30 Sep 2026 research] New pub. OPERATOR UNCERTAIN: entered as ''Stonegate (tenanted)''. CAMRA (updated 8 Sep 2026): became a managed Ei Group pub Feb 2019, reverted to tenanted Apr 2024; leaseholder Stonegate (Ei Group is now part of Stonegate); freeholder Harmsworth Pension Funds Trustees Ltd. The pub''s email domain redcarpubs.com suggests the tenant trades as ''Red Carpet Pubs'' (parked domain, unconfirmed). pint-prices.com links to stonegategroup.co.uk. Check the operator by email (threekings@redcarpubs.com) or in person. It is NOT the old quirky independent pub of older reviews: the 2021 refurb substantially altered the interior and removed the 1938 tiled frontage (CAMRA). Trading (Untappd check-ins 16, 24 and 30 Sep 2026). NO DRINK PRICES ONLINE: Squarespace drinks page lists the range only (no PDFs). Only price: Guinness £6.60 (pint-prices.com, undated). Old Pubs Galore prices (Landlord/Harvey''s £4.50, Dec 2017) not used. Not entered: 4 changing cask handpumps (recent Untappd: Robinsons Dizzy Blonde 30 Sep, Young''s London Original 24 Sep, Rebellion Witchstone 16 Sep, Otter Bitter 18 Aug 2026) and a changing guest cider. Wines listed unpriced. Food prices: toasties £8.50, sandwiches £9.50, burgers £14, pizzas £11.50. OPENED: 1871 (rebuilt for Mann, Crossman & Paulin). Locally listed; Asset of Community Value. No events (events page offers private rooms; ''live sport'' mentioned, no fixtures - sports-tv not tagged); CAMRA mentions vinyl on a turntable. No deals. Food Mon-Sat 12-21, Sun 12-20 (CAMRA). Check: prices, sport on TV, any quiz or music nights. Previously ''Kings of Clerkenwell'' for a while.
