insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-parcel-yard', 'The Parcel Yard', 'King''s Cross Station, Euston Road, London N1C 4AH', 'King''s Cross', 51.53248, -0.1238, 2012, array['historic', 'food', 'sports-tv', 'real-ale-specialist']::text[], 'Fuller''s flagship station pub, opened in 2012 in Lewis Cubitt''s Grade I-listed 1852 parcels office at King''s Cross, right next to Platform 9. It spreads over two floors of rooms around a glass-roofed atrium, with Fuller''s cask ales from around a dozen handpumps and food from breakfast onwards.', 'https://www.parcelyard.co.uk/', 'https://www.parcelyard.co.uk/drink', 'https://www.parcelyard.co.uk/food', 'Fuller''s', '{"0":[["08:00","21:00"]],"1":[["08:00","22:30"]],"2":[["08:00","22:30"]],"3":[["08:00","22:30"]],"4":[["08:00","22:30"]],"5":[["08:00","22:30"]],"6":[["08:00","22:30"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-parcel-yard', 'no', '[1 Oct 2026 research] New pub. Fuller''s managed pub (site code p160; events pubId 8F6142DD29FB4CA282CB3DEBD85F5E78; parcelyard.n1-bookings@fullers.co.uk). Trading (site 2026; events Oct-Nov 2026; Untappd check-ins 27 Sep 2026). Refurbished c. 2025 (Nov 2025 review: ''plush furniture... upped the prices''). NO CURRENT PRICES: the only drinks PDF is ''Sample Drinks Menu - NO PRICES'' (Canva, 18 Mar 2026; ''selections may change seasonally''; guest beers - ask staff). No order-at-table link (check for a table QR code in person). OLD COMMUNITY PRICES (not entered): Pubs and Beer Jun 2023 ''£6.50 a pint for premium strength ales, ESB etc.'', Jun 2018 £5.25; Retired Martin 14 Nov 2024 ESB ''nearing £7''; Tripadvisor Nov 2025 ''London Pride nearly £3 more than my local'' (relative); a large G&T + large rosé ''£29 something'' (Dec 2025). NOT A DRINK DEAL (admin only): pastry + barista hot drink £5, daily 08:00-11:45 (brunch page). Not entered as events: daily Brunch (08:00-11:45, a regular food service) and International Coffee Day (1 Oct 2026, today). Sandwich Day weekday mismatch on the site (see event). HOURS: visible table (Mon-Sat 08:00-22:30, Sun 08:00-21:00); schema.org has the food times; older North London CAMRA page Mon-Sat 08:00-23:00, Sun 09:00-22:30 (out of date). Food Mon-Sat 08:00-21:00, Sun 08:00-20:00. OPENED: 2012 as a pub (19 Mar 2012 per Pubs and Beer); building is Lewis Cubitt''s 1852 parcels office, Grade I. 12 handpumps in two banks (real-ale-specialist tag; Good Beer Guide 2014). dog-friendly not tagged (site says assistance dogs only). Darts, lift, step-free access. CONFLICTS: PDF events phone +44 20 4582 4507 vs main line 020 7713 7258; Pubs and Beer postcode N1C 4AP vs N1C 4AH (used). Check in person: pint prices (Pride, ESB, Guinness, Neck Oil, Peroni) and guest casks.
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-euston-tap', 'The Euston Tap', '190 Euston Road, London NW1 2EF', 'Euston', 51.5269966, -0.1325638, 2010, array['historic', 'craft-beer', 'real-ale-specialist', 'beer-garden', 'dog-friendly']::text[], 'Since 2010 the Euston Tap has occupied one of the two Grade II-listed 1870s stone gatehouses that survived the demolition of the Victorian Euston station. The tiled ground-floor bar is tiny, with a spiral staircase up to more seating and a big heated beer garden, pouring five changing cask ales and around ten kegs, heavy on German and Czech lagers, at prices that are cheap for central London.', 'https://eustontap.com/', 'https://eustontap.com/beer-list', null, 'Bloomsbury Leisure Group', '{"0":[["12:00","22:00"]],"1":[["11:00","23:00"]],"2":[["11:00","23:00"]],"3":[["11:00","23:00"]],"4":[["11:00","23:00"]],"5":[["11:00","23:00"]],"6":[["11:00","23:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-euston-tap', 'no', '[1 Oct 2026 research] New pub. Bloomsbury Leisure Group (also runs the Waterloo, Farringdon and Sheffield Taps); leasehold Euston Tap Ltd; freehold Network Rail. Trading (Untappd check-ins 30 Sep 2026; PINtPOINT tap list 30 Sep; WhatPub updated 28 Jul 2026). NO PRICES ONLINE: the pub''s beer list has names and ABV only (10 keg + 5 cask; ''last updated 24th August'', year not shown); Untappd venue unverified; not on pint-prices.com. PRICES ENTERED: Kirkstall Nectar £4.60 (Untappd check-in 8 Aug 2026) and three Time Out prices from 20 Dec 2024 (out of date, verify). CASK ''FROM £4.20'' (the pub''s own undated site copy: ''sliding scale ranging from the very well priced £4.20 pint of cask beer'') - not entered as a drink price. Older reports (not entered): Time Out Dec 2024 cask ''from £4'', Adnams Blush £5.40, Howling Hops Hazy Pale £5.60, New Bristol Cinder Toffee Stout and JW Lees Stout £5.80; Jaipur £5.40 (Jan 2024); Redemption Trinity £4.50 and Marble stout £4.90 (2023). Range rotates; cheap for central London (cask c. £4-£5.40, keg c. £5.50-£6 in Dec 2024). Check prices on the chalkboard in person. EAST LODGE (old Cider Tap across the road): storage only per a CAMRA surveyor in Jul 2026 - not a separate bar (Untappd still has an ''East Lodge'' venue). No food (Piper''s crisps only). No events (no events page; Instagram 429). CARD ONLY (CAMRA). HOURS: site and CAMRA agree. OPENED: 2010 as a bar, in an 1870s Grade II-listed station lodge. New rear bar Mar 2025; heated outdoor seating Dec 2023. Sports TV only for major events (not tagged). Access: step at entrance, toilets upstairs. AREA: new area Euston (King''s Cross is the nearest existing area). info@eustontap.com.
