insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-tamil-crown', 'The Tamil Crown', '16 Elia Street, London N1 8DE', 'Islington', 51.532, -0.10185, null, array['food']::text[], 'A Victorian corner pub on a quiet backstreet near Angel, long known as The Charles Lamb and reopened in late 2023 as The Tamil Crown by the team behind The Tamil Prince. It''s a low-lit neighbourhood pub serving South Indian sharing plates and spiced cocktails, with a walk-in bar downstairs and a dining room upstairs.', 'https://www.thetamilcrown.com/', 'https://www.thetamilcrown.com/s/The-Tamil-Crown-menus-september.pdf', 'https://www.thetamilcrown.com/s/The-Tamil-Crown-menus-september.pdf', 'Independent (The Tamil Prince team)', '{"0":[["11:00","21:30"]],"1":[["17:00","22:00"]],"2":[["12:00","22:00"]],"3":[["12:00","22:00"]],"4":[["12:00","22:00"]],"5":[["12:00","22:00"]],"6":[["11:00","22:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-tamil-crown', 'yes', 'RENAMED: formerly The Charles Lamb until 2023 (and originally the Prince Albert). [1 Oct 2026 research] Reopened Nov/Dec 2023 as The Tamil Crown, a South Indian food-led pub by Prince Durairaj (ex-Roti King) and Glen Leeson, the team behind The Tamil Prince (Barnsbury); freehold/pubco not found. CAMRA listing updated 23 Jun 2026. The old domain thecharleslambpub.com is parked; older listings (Yelp, Tripadvisor ''Charles Lamb Pub'', inapub, useyourlocal, beerintheevening) describe the pre-2023 pub - do not use. PRICES: the pub''s own menu PDF (created 2 Sep 2026), p.3. Draught measure NOT STATED (pints assumed - confirm); bottle sizes not stated. Wine: house £8/125ml, £32/500ml; bottles £40-£120; Prosecco £7 glass / £40 bottle. Cocktails £13.50-£14.50; 0% cocktails £11.50. NO HISTORIC TAG: per Pubs and Beer the remaining historic fittings were ripped out at the 2023 reopening and it left CAMRA''s National Inventory. No cask ale now (Purity handpumps removed by Apr 2025) - not real-ale-specialist. OPENED left blank: 1839 as the Prince Albert comes only from one enthusiast site; renamed The Charles Lamb 2005. PHONE CONFLICT: 020 3342 0709 (pub site, used) vs 020 7062 7846 (CAMRA). HOURS: pub''s About page (may be kitchen/dining hours); CAMRA shows Mon 17:30-22:00, Tue-Fri 12-15 and 17:30-22:00, Sat 11-22, Sun 11-21. No quiz, music or sport found (Instagram @the_tamil_crown not checked). No deals. Dog-friendly listing (rover) predates the rename - not tagged. Click & collect food via order.thetamilcrown.com (Slerp). info@thetamilcrown.com.
