insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-island-queen', 'The Island Queen', '87 Noel Road, London N1 8HD', 'Islington', 51.533195, -0.098456, 1851, array['historic', 'victorian-interior', 'craft-beer', 'food', 'quiz-night', 'outdoor-drinking']::text[], 'A Victorian gin palace of 1851, refitted in the 1890s and Grade II listed, with one of London''s finest interiors: a tall central island bar with cast-iron columns, etched glass, mirrors and a Lincrusta ceiling. On a quiet street near Angel and the Regent''s Canal, it''s now a Castle pub serving craft beer, pub food and cocktails, with a quiz every Tuesday.', 'https://www.theislandqueenislington.co.uk/', 'https://www.theislandqueenislington.co.uk/menus/drink', 'https://www.theislandqueenislington.co.uk/menus/food', 'Castle (Mitchells & Butlers)', '{"0":[["12:00","22:00"]],"1":[["12:00","23:00"]],"2":[["12:00","23:00"]],"3":[["12:00","23:00"]],"4":[["12:00","23:00"]],"5":[["12:00","00:00"]],"6":[["12:00","00:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-island-queen', 'yes', '[1 Oct 2026 research] New pub. Mitchells & Butlers, Castle brand (same brand as the Crown & Greyhound). Trading (outlet status OPEN, ''Open for Trading'', Christmas 2026 hours loaded). PRICES: M&B order-at-table ''Drinks'' menu (all in stock), seen 1 Oct 2026. M&B IDs: brand 115, brand scalable d4c017c9-da2e-55ee-bf0c-1fa3509e37ef, BunCode 49786 (verified), outlet scalable bf97600b-02c1-53b6-b9ab-a21e41c4a14d, sales area 78044a68-7db2-5b9e-a221-306b1811d7be, TradingEntity 1001379. Spritzes £12.50-£13.95 (Aperol £12.95); cocktails £12.50-£13.95; 0% cocktails £8.25. Wine and soft-drink menus not itemised. DEAL: £8 spritzes Mon-Fri 16:00-19:00 billed ''This Summer'' - still on the page 1 Oct 2026 but may have ended; verify. EVENT: weekly Tuesday quiz 20:00-22:00 (DesignMyNight listings to Sep 2027). Thin cask range: only Black Sheep Bitter (not real-ale-specialist), though it had 50 years in the Good Beer Guide (CAMRA award May 2023; current GBG status not checked). craft-beer tag from Neck Oil, Lightbulb, Arbor/Verdant/Vault City cans. outdoor-drinking from the M&B ''GARDEN'' feature - garden vs pavement unclear, check. FOOD: M&B API food times say ''Closed'' (probably a placeholder); site has food menus - check. ''CAR_PARK'' feature unlikely. OPENED: 1851 (interior altered 1889 and 1897); Grade II (1379875); CAMRA National Inventory three stars. Refurbished Aug 2023. Holidays: 24 Dec 12-22:30; 25 Dec 12-17; 26 Dec 12-22:30; 31 Dec 12-00; 1 Jan 12-22:30. Bottle prices close to the Crown & Greyhound''s.
