insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-southampton-arms', 'The Southampton Arms', '139 Highgate Road, London NW5 1LE', 'Kentish Town', 51.556113, -0.146179, null, array['historic', 'real-ale-specialist', 'craft-beer', 'beer-garden', 'live-music', 'food', 'dog-friendly']::text[], 'A small 1830s London-brick alehouse with a CAMRA-listed historic interior, rescued in 2009 and run ever since as an independent ''ale, cider and meat'' house. Its taps and pumps pour changing beers and ciders from small independent breweries, with pork baps, pies and scotch eggs, records on vinyl, live piano a few nights a week and a walled garden; there''s no TV and no bookings.', 'http://www.thesouthamptonarms.co.uk/', null, null, 'Independent (Thirsty Beast Ltd)', '{"0":[["12:00","22:30"]],"1":[["12:00","23:00"]],"2":[["12:00","23:00"]],"3":[["12:00","23:00"]],"4":[["12:00","23:00"]],"5":[["12:00","00:00"]],"6":[["12:00","00:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-southampton-arms', 'no', '[1 Oct 2026 research] New pub. Independent: leasehold Thirsty Beast Ltd (Peter Holt, who also founded Howling Hops); freehold Tavern Property Co. Reopened as the Southampton Arms in 2009; current manager unknown (Nick Bailey, landlord in 2022, has moved on). Trading (Untappd check-ins 30 Sep 2026; WhatPub updated 24 Jun 2026). WEBSITE: http://www.thesouthamptonarms.co.uk/ kept as given - HTTPS is broken (expired certificate), plain HTTP works; static 2010-era page with no drinks list. PHONE left blank: the pub says it has no phone; 07745 939168 is for emergencies only (contact Peter Holt by email); third-party 07375 755539 unverified. NO PRICES ONLINE: Untappd venue unverified; no dated 2024-26 community price. Historically one flat price per pint: ''£3.40 for any of their pints'' (The Nudge, 29 Dec 2019 - far out of date, not entered). pub-reviews.co.uk ''£4-£5'' is undated and generic. Range: 7 changing cask + real cider (CAMRA); about 8 cask, 8 keg, 8 ciders (Beer Guide London). Howling Hops Tropical Deluxe is in Untappd''s all-time popular drinks (undated) - not entered. PAYMENT: cash AND card per the pub''s homepage (since late 2021 at the latest); several guides still wrongly say cash only. EVENTS: live piano Sun 18:00 and Tue/Wed 20:00 (CAMRA). MONDAY QUIZ UNCONFIRMED: only WhatPub''s description mentions ''Pub quiz Monday'', no time - not entered; check. Records on vinyl (not an event). No deals. OPENED left blank: CAMRA historic-interior text says built in the 1830s; an older WhatPub description says 1938. CAMRA one-star interior; Asset of Community Value. no-music-no-tv not tagged (vinyl plays; no TV). Food: pork baps, pies, sausage rolls, scotch eggs, cheese, pickled eggs; no tea or coffee. No bookings. Access: one step (portable ramp), outside gents, no accessible toilet. Awards: CAMRA London Regional POTY 2011; North London POTY 2011 and 2024; North London Cider Pub of the Year 2017, 2019, 2022, 2023. X @southamptonNW5 (not checked).
insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, food_menu_url, operator, opening_hours) values ('the-pineapple-kentish-town', 'The Pineapple', '51 Leverton Street, London NW5 2NX', 'Kentish Town', 51.55297, -0.13964, 1868, array['historic', 'victorian-interior', 'real-ale-specialist', 'beer-garden', 'food', 'quiz-night', 'dog-friendly']::text[], 'A mid-Victorian back-street local of about 1868, saved from closure by a vigorous local and CAMRA campaign in 2001-02. It has one of London''s finest mahogany bar-backs with etched and gilt mirrors, and today it''s a friendly free house with changing cask ales, a Thai kitchen, a Monday quiz and a conservatory and garden at the back.', 'https://www.thepineapplepubnw5.com/', null, 'https://www.thepineapplepubnw5.com/', 'Independent (free house)', '{"0":[["12:00","22:30"]],"1":[["12:00","23:00"]],"2":[["12:00","23:00"]],"3":[["12:00","23:00"]],"4":[["12:00","23:00"]],"5":[["12:00","00:00"]],"6":[["12:00","00:00"]]}'::jsonb) on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), food_menu_url = coalesce(public.pubs.food_menu_url, excluded.food_menu_url), operator = coalesce(public.pubs.operator, excluded.operator), opening_hours = coalesce(public.pubs.opening_hours, excluded.opening_hours);
insert into public.pub_admin (pub_id, prices_online, notes) values ('the-pineapple-kentish-town', 'no', '[1 Oct 2026 research] New pub. Independent free house; CAMRA lists McGrath, Davies Property Services as operator/leaseholder and an individual as freeholder. Trading (site updated Apr 2026; CAMRA updated 2 Jul 2026). Saved from closure by a 2001-02 local/CAMRA campaign; Asset of Community Value. NO PRICES ONLINE: no drinks menu on the site (food only, Thai kitchen); no Untappd venue found; pint-prices.com 404; Tripadvisor 403. Old Pubs Galore prices (Ghost Ship £4.00 c. 2020, etc.) not used. Check prices in person. Range: 1 regular (house Pineapple Ale = Pedigree) + 3 changing cask (CAMRA; OSM ''3 or 4''); guest names not listed - not entered. DEALS NOT ENTERED (no fixed deal price or % to record): HAPPY HOUR 15:00-19:00 Mon, Wed-Sun and ALL DAY TUESDAY on ''certain drinks'' (pub site; CAMRA says 50p off the house beer, ''which we believe is Pedigree''); CAMRA member discount 20p off a pint; weekday lunch Mon-Fri 12-15 £9.50 a dish or £13.50 for two courses (food). EVENTS: Monday quiz 21:00 (£1 entry); Cheese Tuesday (afternoon, £3 for charity). /new-events says ''no upcoming events''. World Cup 2026 bookings notice is past. OPENED: 1868 (pub site; listing ''C.1868''). Grade II; CAMRA two-star interior; Good Beer Guide; North London POTY (latest 2012); ''Pub of Pubs'' 2024. Kitchen Mon-Fri 12-15 and 18-21:45, Sat-Sun 13-21:45. Upstairs function room (60), conservatory (35); bookings for 10+ only; no under-18s after 19:00. Not tagged: no-music-no-tv (showed World Cup games), sports-tv (not regular). Pub ID the-pineapple-kentish-town to avoid clashes. manager@thepineapplepubnw5.com.
